def get_base_dir():
    """Ubicacion de datos y backups. En Windows: Escritorio/EL MESTIZO."""
    home = Path.home()
    desktop = home / "Desktop"
    if not desktop.exists():
        # Windows en español
        desktop = home / "Escritorio"
    if not desktop.exists():
        desktop = home
    base = desktop / "EL MESTIZO"
    base.mkdir(parents=True, exist_ok=True)
    return base

