    def maquinaria_eliminar(self, maq_id):
        """Si la maquinaria está usada en algún movimiento, la desactiva.
        Si no, la borra."""
        nombre = self.conn.execute(
            "SELECT nombre FROM maquinarias WHERE id=?", (maq_id,)).fetchone()
        if not nombre:
            return False
        usada = 0
        # Buscar en tablas que tengan campo 'maquinaria' (text)
        for tabla in ("campamento", "gtos_particulares"):
            try:
                n = self.conn.execute(
                    f"SELECT COUNT(*) c FROM {tabla} WHERE maquinaria = ?",
                    (nombre["nombre"],)).fetchone()["c"]
                usada += n
            except Exception:
                pass
        if usada > 0:
            self.conn.execute("UPDATE maquinarias SET activo=0 WHERE id=?", (maq_id,))
        else:
            self.conn.execute("DELETE FROM maquinarias WHERE id=?", (maq_id,))
        self.conn.commit()
        return usada > 0

