    def fc_banco_saldo_calculado(self, banco_id):
        """Saldo calculado = saldo_manual - (cheques Pendientes del banco).
        Los cheques Cobrados ya están aplicados en el saldo del banco real,
        así que no se restan del calculado."""
        b = self.fc_banco_get(banco_id)
        if not b:
            return 0
        saldo = float(b.get("saldo_manual") or 0)
        # Restar cheques pendientes (porque salen del saldo cuando se cobren)
        ch_pend = self.conn.execute(
            "SELECT COALESCE(SUM(monto), 0) c FROM fc_cheques WHERE banco_id=? AND estado='Pendiente'",
            (banco_id,)).fetchone()["c"]
        return saldo - ch_pend

    # ---------- Cheques ----------
    def fc_cheque_listar(self, fecha_desde=None, fecha_hasta=None,
                          banco_id=None, estado=None, beneficiario=None,
                          fecha_cobro_desde=None, fecha_cobro_hasta=None):
        q = """SELECT c.*, b.nombre AS banco_nombre
               FROM fc_cheques c
               LEFT JOIN fc_bancos b ON b.id = c.banco_id
               WHERE 1=1"""
        params = []
        if fecha_desde:
            q += " AND c.fecha_emision >= ?"; params.append(fecha_desde)
        if fecha_hasta:
            q += " AND c.fecha_emision <= ?"; params.append(fecha_hasta)
        if fecha_cobro_desde:
            q += " AND c.fecha_cobro_estimada >= ?"; params.append(fecha_cobro_desde)
        if fecha_cobro_hasta:
            q += " AND c.fecha_cobro_estimada <= ?"; params.append(fecha_cobro_hasta)
        if banco_id:
            q += " AND c.banco_id = ?"; params.append(banco_id)
        if estado:
            q += " AND c.estado = ?"; params.append(estado)
        if beneficiario:
            q += " AND c.beneficiario LIKE ?"; params.append(f"%{beneficiario}%")
        q += " ORDER BY c.fecha_emision DESC, c.id DESC"
        return [dict(r) for r in self.conn.execute(q, params)]

    def fc_cheque_get(self, ch_id):
        r = self.conn.execute("SELECT * FROM fc_cheques WHERE id=?", (ch_id,)).fetchone()
        return dict(r) if r else None

    def fc_cheque_insertar(self, fecha_emision, banco_id, nro_cheque, beneficiario,
                            monto, fecha_cobro_estimada=None, observaciones=None):
        self.conn.execute("""INSERT INTO fc_cheques
            (fecha_emision, banco_id, nro_cheque, beneficiario, monto,
             fecha_cobro_estimada, observaciones, estado)
            VALUES (?, ?, ?, ?, ?, ?, ?, 'Pendiente')""",
            (fecha_emision, banco_id, nro_cheque, beneficiario, monto,
             fecha_cobro_estimada, observaciones))
        self.conn.commit()

    def fc_cheque_actualizar(self, ch_id, **campos):
        if not campos: return
        sets = ", ".join(f"{k}=?" for k in campos.keys())
        params = list(campos.values()) + [ch_id]
        self.conn.execute(f"UPDATE fc_cheques SET {sets} WHERE id=?", params)
        self.conn.commit()

    def fc_cheque_confirmar(self, ch_id, estado, fecha_real=None, obs=None):
        """estado: 'Cobrado' / 'Rechazado' / 'Anulado'"""
        params = [estado, fecha_real]
        sql = "UPDATE fc_cheques SET estado=?, fecha_cobro_real=?"
        if obs is not None:
            sql += ", observaciones=?"
            params.append(obs)
        sql += " WHERE id=?"
        params.append(ch_id)
        self.conn.execute(sql, params)
        self.conn.commit()

    def fc_cheque_eliminar(self, ch_id):
        self.conn.execute("DELETE FROM fc_cheques WHERE id=?", (ch_id,))
        self.conn.commit()

    def fc_cheque_mensual(self, fecha_desde=None, fecha_hasta=None, banco_id=None):
        """Devuelve dict {YYYY-MM: {emitidos, cobrados, pendientes}} para gráfico mensual."""
        q = "SELECT * FROM fc_cheques WHERE 1=1"
        params = []
        if fecha_desde:
            q += " AND fecha_emision >= ?"; params.append(fecha_desde)
        if fecha_hasta:
            q += " AND fecha_emision <= ?"; params.append(fecha_hasta)
        if banco_id:
            q += " AND banco_id = ?"; params.append(banco_id)
        out = {}
        for r in self.conn.execute(q, params):
            # Mes a partir de la fecha relevante: cobrado usa fecha_cobro_real, pendiente usa emisión
            fecha_ref = r["fecha_cobro_real"] if r["estado"] == "Cobrado" and r["fecha_cobro_real"] else r["fecha_emision"]
            mes = fecha_ref[:7] if fecha_ref else ""
            if not mes: continue
            if mes not in out:
                out[mes] = {"emitidos": 0, "cobrados": 0, "pendientes": 0, "rechazados": 0}
            out[mes]["emitidos"] += r["monto"]
            if r["estado"] == "Cobrado":
                out[mes]["cobrados"] += r["monto"]
            elif r["estado"] == "Pendiente":
                out[mes]["pendientes"] += r["monto"]
            elif r["estado"] in ("Rechazado", "Anulado"):
                out[mes]["rechazados"] += r["monto"]
        return out

