    # ---------- Cuentas a pagar/cobrar (lógica común) ----------
    def fc_cuenta_listar(self, tabla, fecha_desde=None, fecha_hasta=None,
                           categoria_id=None, estado=None, moneda=None,
                           desc_like=None, fecha_field="fecha_vencimiento"):
        """tabla: 'fc_cuentas_pagar' o 'fc_cuentas_cobrar'"""
        cat_tabla = "fc_cat_pagar" if tabla == "fc_cuentas_pagar" else "fc_cat_cobrar"
        q = f"""SELECT c.*, cat.nombre AS categoria_nombre
                FROM {tabla} c
                LEFT JOIN {cat_tabla} cat ON cat.id = c.categoria_id
                WHERE 1=1"""
        params = []
        if fecha_desde:
            q += f" AND c.{fecha_field} >= ?"; params.append(fecha_desde)
        if fecha_hasta:
            q += f" AND c.{fecha_field} <= ?"; params.append(fecha_hasta)
        if categoria_id:
            q += " AND c.categoria_id = ?"; params.append(categoria_id)
        if estado:
            q += " AND c.estado = ?"; params.append(estado)
        if moneda:
            q += " AND c.moneda = ?"; params.append(moneda)
        if desc_like:
            q += " AND c.descripcion LIKE ?"; params.append(f"%{desc_like}%")
        q += f" ORDER BY c.{fecha_field} DESC, c.id DESC"
        return [dict(r) for r in self.conn.execute(q, params)]

    def fc_cuenta_get(self, tabla, c_id):
        r = self.conn.execute(f"SELECT * FROM {tabla} WHERE id=?", (c_id,)).fetchone()
        return dict(r) if r else None

    def fc_cuenta_insertar(self, tabla, **datos):
        cols = ", ".join(datos.keys())
        placeholders = ", ".join("?" * len(datos))
        cur = self.conn.execute(
            f"INSERT INTO {tabla} ({cols}) VALUES ({placeholders})",
            list(datos.values()))
        self.conn.commit()
        return cur.lastrowid

    def fc_cuenta_actualizar(self, tabla, c_id, **campos):
        if not campos: return
        sets = ", ".join(f"{k}=?" for k in campos.keys())
        params = list(campos.values()) + [c_id]
        self.conn.execute(f"UPDATE {tabla} SET {sets} WHERE id=?", params)
        self.conn.commit()

    def fc_cuenta_confirmar(self, tabla, c_id, estado, fecha_real=None, obs=None):
        """estado: 'Pagado'/'Cobrado' / 'Rechazado' / 'Anulado'"""
        fecha_field = "fecha_pago_real" if tabla == "fc_cuentas_pagar" else "fc_cuenta_cobrar"
        if tabla == "fc_cuentas_cobrar":
            fecha_field = "fecha_cobro_real"
        params = [estado, fecha_real]
        sql = f"UPDATE {tabla} SET estado=?, {fecha_field}=?"
        if obs is not None:
            sql += ", observaciones=?"
            params.append(obs)
        # Si es una cuenta de arrendamiento y se está pagando, congelar el monto
        # (dejar de recalcularlo con el precio del día).
        if tabla == "fc_cuentas_pagar" and estado in ("Pagado", "Anulado"):
            sql += ", arr_recalcular=0"
        sql += " WHERE id=?"
        params.append(c_id)
        self.conn.execute(sql, params)
        self.conn.commit()

    def fc_cuenta_eliminar(self, tabla, c_id):
        self.conn.execute(f"DELETE FROM {tabla} WHERE id=?", (c_id,))
        self.conn.commit()

