    def fc_cuenta_mensual(self, tabla, fecha_desde=None, fecha_hasta=None,
                            categoria_id=None):
        """Mensualiza por fecha de vencimiento.
        Devuelve {YYYY-MM: {total, pendiente, pagado_o_cobrado, rechazado}}"""
        rows = self.fc_cuenta_listar(
            tabla, fecha_desde=fecha_desde, fecha_hasta=fecha_hasta,
            categoria_id=categoria_id)
        out = {}
        for r in rows:
            mes = (r["fecha_vencimiento"] or r["fecha_emision"] or "")[:7]
            if not mes: continue
            out.setdefault(mes, {"total": 0, "pendiente": 0, "completado": 0, "rechazado": 0})
            monto = float(r["monto_ars"] or 0)
            out[mes]["total"] += monto
            if r["estado"] == "Pendiente":
                out[mes]["pendiente"] += monto
            elif r["estado"] in ("Pagado", "Cobrado"):
                out[mes]["completado"] += monto
            elif r["estado"] in ("Rechazado", "Anulado"):
                out[mes]["rechazado"] += monto
        return out

    # ---------- Entidades de Dólar ----------
    def fc_entidad_listar(self, solo_activos=True):
        q = "SELECT * FROM fc_entidades_dolar"
        if solo_activos:
            q += " WHERE activo=1"
        q += " ORDER BY nombre"
        return [dict(r) for r in self.conn.execute(q)]

    def fc_entidad_get(self, ent_id):
        r = self.conn.execute("SELECT * FROM fc_entidades_dolar WHERE id=?", (ent_id,)).fetchone()
        return dict(r) if r else None

    def fc_entidad_insertar(self, nombre, saldo_inicial=0, fecha_inicial=None):
        self.conn.execute(
            "INSERT INTO fc_entidades_dolar (nombre, saldo_inicial_usd, fecha_saldo_inicial) VALUES (?, ?, ?)",
            (nombre.strip(), saldo_inicial, fecha_inicial))
        self.conn.commit()

    def fc_entidad_actualizar(self, ent_id, nombre, saldo_inicial=0,
                                fecha_inicial=None, activo=1):
        self.conn.execute("""UPDATE fc_entidades_dolar
            SET nombre=?, saldo_inicial_usd=?, fecha_saldo_inicial=?, activo=?
            WHERE id=?""",
            (nombre.strip(), saldo_inicial, fecha_inicial, 1 if activo else 0, ent_id))
        self.conn.commit()

    def fc_entidad_eliminar(self, ent_id):
        usado = self.conn.execute(
            "SELECT COUNT(*) c FROM fc_mov_dolar WHERE entidad_id=?", (ent_id,)).fetchone()["c"]
        if usado > 0:
            self.conn.execute("UPDATE fc_entidades_dolar SET activo=0 WHERE id=?", (ent_id,))
        else:
            self.conn.execute("DELETE FROM fc_entidades_dolar WHERE id=?", (ent_id,))
        self.conn.commit()
        return usado > 0

    def fc_entidad_saldo(self, ent_id):
        """Saldo en USD = saldo_inicial + suma(cantidad_usd de movimientos)."""
        e = self.fc_entidad_get(ent_id)
        if not e:
            return 0
        saldo = float(e.get("saldo_inicial_usd") or 0)
        suma = self.conn.execute(
            "SELECT COALESCE(SUM(cantidad_usd), 0) s FROM fc_mov_dolar WHERE entidad_id=?",
            (ent_id,)).fetchone()["s"]
        return saldo + float(suma or 0)

