    def sbm_actualizar(self, mov_id, fecha, tipo, deposito_id, cultivo, campania,
                         kg, observaciones=""):
        self.conn.execute("""UPDATE stock_bolson_mov
            SET fecha=?, tipo=?, deposito_id=?, cultivo=?, campania=?, kg=?, observaciones=?
            WHERE id=?""",
            (fecha, tipo, deposito_id, cultivo, campania, kg,
             observaciones or "", mov_id))
        self.conn.commit()

    def sbm_eliminar(self, mov_id):
        self.conn.execute("DELETE FROM stock_bolson_mov WHERE id=?", (mov_id,))
        self.conn.commit()

    def sbm_stock_por_bolson(self, fecha_hasta=None, deposito_id=None,
                                cultivo=None, campania=None):
        """Calcula sub-stock por (bolsón, cultivo, campaña).
        Solo considera depósitos cuya ubicación contiene 'bolson'.

        Devuelve lista de dicts: {deposito_id, deposito_nombre, deposito_ubicacion,
                                  cultivo, campania, sub_entradas, sub_salidas, sub_stock}
        """
        q = """SELECT m.*, d.nombre AS deposito_nombre, d.ubicacion AS deposito_ubicacion
               FROM stock_bolson_mov m
               LEFT JOIN depositos d ON d.id = m.deposito_id
               WHERE 1=1"""
        params = []
        if fecha_hasta:
            q += " AND m.fecha <= ?"; params.append(fecha_hasta)
        if cultivo:
            q += " AND m.cultivo = ?"; params.append(cultivo)
        if campania:
            q += " AND m.campania = ?"; params.append(campania)
        if deposito_id:
            q += " AND m.deposito_id = ?"; params.append(deposito_id)

        acc = {}  # (dep_id, nombre, ubicacion, cult, camp) -> {ent, sal}
        for r in self.conn.execute(q, params):
            # Filtro insensible a tildes/mayúsculas
            if not es_ubicacion_bolson(r["deposito_ubicacion"]):
                continue
            kg = float(r["kg"])
            key = (r["deposito_id"], r["deposito_nombre"], r["deposito_ubicacion"],
                   r["cultivo"], r["campania"] or "")
            if key not in acc:
                acc[key] = {"sub_entradas": 0, "sub_salidas": 0}
            if r["tipo"] == "Sub-entrada":
                acc[key]["sub_entradas"] += kg
            elif r["tipo"] == "Sub-salida":
                acc[key]["sub_salidas"] += kg

        out = []
        for (dep_id, dep_nombre, dep_ubic, cult, camp), v in acc.items():
            out.append({
                "deposito_id": dep_id,
                "deposito_nombre": dep_nombre,
                "deposito_ubicacion": dep_ubic or "",
                "cultivo": cult,
                "campania": camp,
                "sub_entradas": v["sub_entradas"],
                "sub_salidas": v["sub_salidas"],
                "sub_stock": v["sub_entradas"] - v["sub_salidas"],
            })
        out.sort(key=lambda x: (x["deposito_nombre"], x["cultivo"], x["campania"]))
        return out


    def kg_vendidos_por_campo(self, campania, cultivo):
        """Suma de 'unidades' de movimientos Venta+Cereal para ese cultivo y campaña,
        agrupado por establecimiento.

        El match es insensible a tildes y mayúsculas para cultivo y establecimiento.
        Se excluyen los movimientos con establecimiento 'TODOS' (esos son los
        movimientos antes del reparto; los que ya están repartidos van a su campo).
        """
        # Traemos todas las ventas de Cereal de la campaña, sin filtrar por cultivo
        # en SQL (lo hacemos en Python con normalize_name para ser tolerantes).
        rows = self.conn.execute("""
            SELECT establecimiento, cultivo, COALESCE(SUM(unidades), 0) AS kg
            FROM campos
            WHERE tipo_mov='Venta'
              AND rubro='Cereal'
              AND campania=?
              AND establecimiento NOT LIKE 'TODOS%'
              AND (unidades IS NOT NULL AND unidades > 0)
            GROUP BY establecimiento, cultivo
        """, (campania,))
        cult_norm = normalize_name(cultivo)
        out = {}
        for r in rows:
            if normalize_name(r["cultivo"]) == cult_norm:
                out[r["establecimiento"]] = out.get(r["establecimiento"], 0) + float(r["kg"] or 0)
        return out

    def balance_por_cultivo(self, cultivo, campania, campo=None):
        """Calcula el balance económico de un cultivo+campaña, opcionalmente
        restringido a un campo específico.

        Si `campo` es None o "" o "TODOS": balance global del cultivo+campaña.
        Si `campo` es un nombre específico: balance solo para ese campo.

        Aprovecha que los repartos (TODOS+Cult, Campo+TODOS_cult, TODOS+TODOS,
        arrendamientos) ya están materializados en filas vinculadas (link_id) en
        la tabla `campos`. Por eso una simple suma por campo+cultivo+campaña ya
        incluye TODO lo repartido.

        Devuelve un dict con:
        - filtros: {cultivo, campania, campo}
        - ventas_total, gastos_total
        - balance_operativo (ventas - gastos)
        - ventas_por_rubro: [{rubro, monto, pct}]
        - gastos_por_rubro: [{rubro, monto, pct}]
        - kg_cosechados, kg_vendidos, kg_sin_vender
        - precio_kg_ars (puede ser 0 si no hay precio cargado)
        - valor_stock_ars
        - balance_integral (operativo + valor_stock)
        - movs_ventas: lista de movimientos de venta usados
        - movs_gastos: lista de movimientos de gasto usados
        """
        cult_norm = normalize_name(cultivo)
        es_todos = (not campo) or campo == TODOS_LABEL or normalize_name(campo) == "todos"

        # Traer TODOS los movimientos de la campaña con ese cultivo (sea match exacto)
        # Filtramos en Python para tolerancia a tildes.
        rows = self.conn.execute("""
            SELECT * FROM campos
            WHERE campania = ?
              AND (cultivo IS NOT NULL AND cultivo != '')
        """, (campania,)).fetchall()

        movs_ventas = []
        movs_gastos = []
        ventas_total = 0.0
        gastos_total = 0.0
        ventas_por_rubro = {}
        gastos_por_rubro = {}

        # También capturamos movimientos con cultivo=TODOS para informar
        # (ya están repartidos, no se suman; solo se reportan)
        for r in rows:
            cult_row = r["cultivo"] or ""
            estab = r["establecimiento"] or ""
            # Filtrar por campo si pidieron uno específico
            if not es_todos:
                if normalize_name(estab) != normalize_name(campo):
                    continue
            # Saltar movimientos con establecimiento TODOS (esos son las cabezas
            # del reparto, las filas materializadas tienen el campo específico)
            if normalize_name(estab).startswith("todos"):
                continue
            # Solo del cultivo pedido
            if normalize_name(cult_row) != cult_norm:
                continue
            monto = float(r["monto"] or 0)
            tipo = r["tipo_mov"] or ""
            rubro = r["rubro"] or "(sin rubro)"
            d = dict(r)
            if tipo == "Venta":
                ventas_total += monto
                ventas_por_rubro[rubro] = ventas_por_rubro.get(rubro, 0) + monto
                movs_ventas.append(d)
            elif tipo == "Gasto":
                gastos_total += monto
                gastos_por_rubro[rubro] = gastos_por_rubro.get(rubro, 0) + monto
                movs_gastos.append(d)

        # Convertir a listas con %
        def _con_pct(diccionario, total):
            out = []
            for rubro, monto in sorted(diccionario.items(),
                                         key=lambda x: -abs(x[1])):
                pct = (monto / total * 100) if total > 0 else 0
                out.append({"rubro": rubro, "monto": monto, "pct": pct})
            return out

        ventas_por_rubro_list = _con_pct(ventas_por_rubro, ventas_total)
        gastos_por_rubro_list = _con_pct(gastos_por_rubro, gastos_total)

        # ---- Stock cereal ----
        # kg cosechados (de stock_cereal)
        if es_todos:
            cos_dict = self.kg_cosechados_por_campo(campania, cultivo)
            kg_cos = sum(cos_dict.values())
        else:
            cos_dict = self.kg_cosechados_por_campo(campania, cultivo)
            kg_cos = 0
            for estab, kg in cos_dict.items():
                if normalize_name(estab) == normalize_name(campo):
                    kg_cos = kg
                    break

        # kg vendidos
        if es_todos:
            vend_dict = self.kg_vendidos_por_campo(campania, cultivo)
            kg_vend = sum(vend_dict.values())
        else:
            vend_dict = self.kg_vendidos_por_campo(campania, cultivo)
            kg_vend = 0
            for estab, kg in vend_dict.items():
                if normalize_name(estab) == normalize_name(campo):
                    kg_vend = kg
                    break

        kg_sin_vender = max(0, kg_cos - kg_vend)

        # ---- Precio del cereal (mismo método que en Análisis: precios_cereal) ----
        precio_kg_ars = 0.0
        try:
            p = self.conn.execute(
                "SELECT precio_ars_kg FROM precios_cereal WHERE cultivo = ? LIMIT 1",
                (cultivo,)).fetchone()
            if p:
                precio_kg_ars = float(p["precio_ars_kg"] or 0)
            else:
                # Tolerante a tildes
                for pr in self.conn.execute("SELECT cultivo, precio_ars_kg FROM precios_cereal"):
                    if normalize_name(pr["cultivo"]) == cult_norm:
                        precio_kg_ars = float(pr["precio_ars_kg"] or 0)
                        break
        except Exception:
            precio_kg_ars = 0.0

        valor_stock_ars = kg_sin_vender * precio_kg_ars

        balance_operativo = ventas_total - gastos_total
        balance_integral = balance_operativo + valor_stock_ars

        return {
            "filtros": {
                "cultivo": cultivo,
                "campania": campania,
                "campo": campo if not es_todos else "TODOS",
            },
            "ventas_total": ventas_total,
            "gastos_total": gastos_total,
            "balance_operativo": balance_operativo,
            "ventas_por_rubro": ventas_por_rubro_list,
            "gastos_por_rubro": gastos_por_rubro_list,
            "kg_cosechados": kg_cos,
            "kg_vendidos": kg_vend,
            "kg_sin_vender": kg_sin_vender,
            "precio_kg_ars": precio_kg_ars,
            "valor_stock_ars": valor_stock_ars,
            "balance_integral": balance_integral,
            "movs_ventas": movs_ventas,
            "movs_gastos": movs_gastos,
        }

    def balance_por_ganaderia(self, fecha_desde, fecha_hasta, campo=None):
        """Calcula el balance económico de la ganadería en un rango de fechas,
        opcionalmente restringido a un campo específico.

        Si `campo` es None / "" / "TODOS": balance global de todos los campos.
        Si `campo` es un nombre específico: solo ese campo.

        Aprovecha que los repartos por has ganaderas (TODOS, agrupaciones,
        arrendamientos parte ganadera) ya están materializados en la tabla
        `campos` con link_id, así una suma simple por (campo+sector=Ganadero)
        ya incluye todo lo repartido.

        Valor stock: solo categorías Terneras + Terneros + Novillitos + Novillos + Vaquillonas,
        multiplicadas por su precio (precio_animal de categorias_mercado).
        Stock tomado del último valor cargado <= fecha_hasta en stock_ganadero.

        Devuelve dict con:
        - filtros: {fecha_desde, fecha_hasta, campo}
        - ventas_total, gastos_total
        - balance_operativo
        - ventas_por_rubro, gastos_por_rubro: listas con {rubro, monto, pct}
        - stock_detalle: lista con {categoria, cantidad, precio_animal, subtotal}
        - valor_stock_ars
        - balance_integral
        - movs_ventas, movs_gastos
        """
        es_todos = (not campo) or campo == TODOS_LABEL or normalize_name(campo) == "todos"

        # Movimientos ganaderos en el rango de fechas
        q = """SELECT * FROM campos
               WHERE sector = 'Ganadero'
                 AND fecha >= ? AND fecha <= ?"""
        rows = self.conn.execute(q, (fecha_desde, fecha_hasta)).fetchall()

        movs_ventas = []
        movs_gastos = []
        ventas_total = 0.0
        gastos_total = 0.0
        ventas_por_rubro = {}
        gastos_por_rubro = {}

        for r in rows:
            estab = r["establecimiento"] or ""
            # Saltar cabeceras del reparto (filas materializadas tienen el campo específico)
            if normalize_name(estab).startswith("todos"):
                continue
            # Filtrar por campo si pidieron uno específico
            if not es_todos:
                if normalize_name(estab) != normalize_name(campo):
                    continue
            monto = float(r["monto"] or 0)
            tipo = r["tipo_mov"] or ""
            rubro = r["rubro"] or "(sin rubro)"
            d = dict(r)
            if tipo == "Venta":
                ventas_total += monto
                ventas_por_rubro[rubro] = ventas_por_rubro.get(rubro, 0) + monto
                movs_ventas.append(d)
            elif tipo == "Gasto":
                gastos_total += monto
                gastos_por_rubro[rubro] = gastos_por_rubro.get(rubro, 0) + monto
                movs_gastos.append(d)

        # Convertir a listas con %
        def _con_pct(diccionario, total):
            out = []
            for rubro, monto in sorted(diccionario.items(),
                                         key=lambda x: -abs(x[1])):
                pct = (monto / total * 100) if total > 0 else 0
                out.append({"rubro": rubro, "monto": monto, "pct": pct})
            return out

        ventas_por_rubro_list = _con_pct(ventas_por_rubro, ventas_total)
        gastos_por_rubro_list = _con_pct(gastos_por_rubro, gastos_total)

        # ---- Valor del stock ganado ----
        # Stock a fecha_hasta (último cargado <= fecha)
        stock_rows = self.conn.execute("""
            SELECT establecimiento, categoria, cantidad, fecha
            FROM stock_ganadero
            WHERE fecha <= ?
            ORDER BY fecha DESC, establecimiento, categoria
        """, (fecha_hasta,)).fetchall()
        # Nombre oficial de establecimientos (desde tabla establecimientos)
        # para preferirlo cuando hay variantes de mayúsculas
        oficial = {}
        for e in self.conn.execute("SELECT nombre FROM establecimientos"):
            oficial[normalize_name(e["nombre"])] = e["nombre"]

        # Agrupamos por (norm_estab, norm_cat) y guardamos:
        # - cantidad (suma de variantes de mayúsculas en la MISMA fecha,
        #   o último valor si vienen de fechas distintas)
        # - estab_display: nombre oficial o título si no hay oficial
        # - cat_display: TITLE-CASE
        # - fecha: fecha del último registro usado
        stock_por_estab = {}
        # (norm_estab, norm_cat) -> {"estab_disp": str, "cat_disp": str, "cant": float, "fecha": str}
        agrup = {}
        for r in stock_rows:
            est = r["establecimiento"] or ""
            cat = r["categoria"] or ""
            key = (normalize_name(est), normalize_name(cat))
            est_disp = oficial.get(normalize_name(est),
                                       est.title() if est == est.upper() and len(est) > 1 else est)
            cat_disp = cat.title() if cat else cat
            if key not in agrup:
                # Primera vez que aparece esta combinación: tomar como "última" porque está
                # ordenado por fecha DESC.
                agrup[key] = {
                    "estab_disp": est_disp,
                    "cat_disp": cat_disp,
                    "cant": float(r["cantidad"] or 0),
                    "fecha": r["fecha"],
                }
            else:
                # Si es de la MISMA fecha, sumar (porque son variantes de mayúsculas
                # del mismo nombre — ej. DON BONIFACIO y Don Bonifacio en 27/05/2026).
                # Si es de fecha más vieja, ignorar (queremos el último).
                if r["fecha"] == agrup[key]["fecha"]:
                    agrup[key]["cant"] += float(r["cantidad"] or 0)
        # Convertir el agrup a stock_por_estab usando los nombres "display"
        for (ne, nc), info in agrup.items():
            stock_por_estab.setdefault(info["estab_disp"], {})[info["cat_disp"]] = info["cant"]

        # Precios de mercado por categoría
        precios = {}
        for r in self.conn.execute("SELECT * FROM categorias_mercado"):
            precios[(r["categoria_stock"] or "").upper().strip()] = {
                "kg_animal": r["kg_animal"] or 0,
                "precio_kg": r["precio_kg"] or 0,
                "precio_animal": r["precio_animal"] or 0,
            }

        # SOLO estas 5 categorías cuentan para el valor stock del balance ganadería
        CATEGORIAS_VALIDAS = {"TERNERAS", "TERNEROS", "NOVILLITOS", "NOVILLOS", "VAQUILLONAS"}

        stock_detalle = []
        valor_stock_total = 0.0
        # Iterar por establecimientos relevantes
        cats_encontradas = set()  # categorías VALIDAS efectivamente encontradas
        fecha_max_stock_usado = None  # fecha más reciente del stock que se está usando
        fecha_min_stock_usado = None  # fecha más vieja del stock que se está usando
        for estab, cats in stock_por_estab.items():
            # Filtrar por campo si aplica
            if not es_todos and normalize_name(estab) != normalize_name(campo):
                continue
            for cat, cant in cats.items():
                cat_upper = (cat or "").upper().strip()
                if cat_upper not in CATEGORIAS_VALIDAS:
                    continue
                cats_encontradas.add(cat_upper)
                pinfo = precios.get(cat_upper, {})
                precio_animal = pinfo.get("precio_animal", 0) or 0
                subtotal = cant * precio_animal
                valor_stock_total += subtotal
                stock_detalle.append({
                    "establecimiento": estab,
                    "categoria": cat.title() if cat else cat_upper,
                    "cantidad": cant,
                    "precio_animal": precio_animal,
                    "kg_animal": pinfo.get("kg_animal", 0) or 0,
                    "precio_kg": pinfo.get("precio_kg", 0) or 0,
                    "subtotal": subtotal,
                    "valorado": precio_animal > 0,
                })
        # Detectar la fecha más reciente / más antigua del stock usado
        for (ne, nc), info in agrup.items():
            if nc.upper() not in {c.lower() for c in CATEGORIAS_VALIDAS} \
                    and info["cat_disp"].upper().strip() not in CATEGORIAS_VALIDAS:
                continue
            # Filtrar por campo si aplica
            if not es_todos and ne != normalize_name(campo):
                continue
            f = info["fecha"]
            if fecha_max_stock_usado is None or f > fecha_max_stock_usado:
                fecha_max_stock_usado = f
            if fecha_min_stock_usado is None or f < fecha_min_stock_usado:
                fecha_min_stock_usado = f

        # ---- Avisos sobre el stock ----
        avisos_stock = []
        if not stock_detalle:
            # No hay nada valorizable
            if any(stock_rows):
                # Hay stock pero ninguna categoría válida
                cats_existentes = sorted({(r["categoria"] or "").upper().strip()
                                            for r in stock_rows})
                avisos_stock.append(
                    f"⚠ Al {fmt_fecha(fecha_hasta)} hay stock cargado pero NO incluye ninguna "
                    f"de las categorías valorizables (Terneras, Terneros, Novillitos, Novillos, "
                    f"Vaquillonas). Categorías encontradas en esa fecha: "
                    f"{', '.join(c for c in cats_existentes if c) or '(ninguna)'}.")
            else:
                avisos_stock.append(
                    f"⚠ No hay ningún stock ganadero cargado con fecha ≤ {fmt_fecha(fecha_hasta)}.")
        else:
            # Hay algunas categorías valorizadas: avisar si faltan
            faltan = CATEGORIAS_VALIDAS - cats_encontradas
            if faltan:
                avisos_stock.append(
                    f"⚠ Al {fmt_fecha(fecha_hasta)} faltan estas categorías valorizables: "
                    f"{', '.join(sorted(faltan))}. El valor del stock puede estar subestimado.")
            # Avisar si las fechas del stock usado son muy distintas a la fecha de corte
            if fecha_max_stock_usado and fecha_max_stock_usado != fecha_hasta:
                try:
                    d_corte = dt.datetime.strptime(fecha_hasta, "%Y-%m-%d").date()
                    d_max = dt.datetime.strptime(fecha_max_stock_usado, "%Y-%m-%d").date()
                    dias = (d_corte - d_max).days
                    if dias > 90:
                        avisos_stock.append(
                            f"ℹ️ El stock más reciente usado es del {fmt_fecha(fecha_max_stock_usado)} "
                            f"({dias} días antes del corte). Si tenés cargas más nuevas, podrían reflejar mejor el momento.")
                except Exception:
                    pass

        # Ordenar por establecimiento + categoría
        stock_detalle.sort(key=lambda d: (d["establecimiento"], d["categoria"]))

        balance_operativo = ventas_total - gastos_total
        balance_integral = balance_operativo + valor_stock_total

        return {
            "filtros": {
                "fecha_desde": fecha_desde,
                "fecha_hasta": fecha_hasta,
                "campo": campo if not es_todos else "TODOS",
            },
            "ventas_total": ventas_total,
            "gastos_total": gastos_total,
            "balance_operativo": balance_operativo,
            "ventas_por_rubro": ventas_por_rubro_list,
            "gastos_por_rubro": gastos_por_rubro_list,
            "stock_detalle": stock_detalle,
            "valor_stock_ars": valor_stock_total,
            "balance_integral": balance_integral,
            "avisos_stock": avisos_stock,
            "movs_ventas": movs_ventas,
            "movs_gastos": movs_gastos,
        }

    def dashboard_data(self, fecha_desde=None, fecha_hasta=None,
                        campania=None, campo=None, modo_stock="patrimonial"):
        """Calcula TODOS los datos agregados que necesita el Dashboard.

        Reúne información de las 3 fuentes: campos, campamento, gtos_particulares.

        Filtros (todos opcionales):
        - fecha_desde, fecha_hasta: rango (ISO o None)
        - campania: solo afecta a `campos`
        - campo: filtro de establecimiento, solo afecta a `campos`
                 ("TODOS" / None = sin filtro)
        - modo_stock: "patrimonial" (todo el stock hasta esta campaña incl. anteriores
                       y todas las categorías de ganado) o "ejercicio" (solo esta
                       campaña de cereal y solo Terneras/Terneros de ganado).

        Devuelve un dict gigante con:
        - filtros: {desde, hasta, campania, campo}
        - campos: {ventas, gastos, balance, val_stock_ganado, val_stock_cereal, integral, ...}
        - campamento: {gastos, ventas, balance, top_rubros, top_maquinarias}
        - gtos_particulares: {gastos, ventas, balance, top_rubros}
        - consolidado: {total_ventas, total_gastos, balance_total, val_stocks, integral_total}
        - top_rubros_gasto_consolidado: lista [{fuente, rubro, monto, pct}]
        - top_rubros_venta_consolidado: lista
        - performance_campos: lista [{campo, ventas, gastos, balance, margen_pct}]
        - top_cultivos: lista [{cultivo, ventas, gastos, balance}]
        - alertas: lista de strings (deficiencias detectadas)
        - eficiencias: lista de strings (cosas positivas detectadas)
        """
        # --- Helper interno para WHERE de fechas ---
        def _wfechas(prefix=""):
            wh, params = [], []
            if fecha_desde:
                wh.append(f"{prefix}fecha >= ?"); params.append(fecha_desde)
            if fecha_hasta:
                wh.append(f"{prefix}fecha <= ?"); params.append(fecha_hasta)
            return wh, params

        # ====================================================
        # 1. CAMPOS
        # ====================================================
        es_todos_campo = (not campo) or campo == TODOS_LABEL or normalize_name(campo) == "todos"
        q = "SELECT * FROM campos WHERE 1=1"
        params = []
        wh, p = _wfechas()
        if wh:
            q += " AND " + " AND ".join(wh); params.extend(p)
        # NOTA: el filtro de campaña NO se aplica a los movimientos.
        # La campaña solo se usa para el cálculo del Val. Stock Cereal
        # (define cuál es "la campaña actual" en modo ejercicio o el límite
        # de campañas a incluir en modo patrimonial).

        rows_campos = list(self.conn.execute(q, params))

        ventas_campos = 0.0
        gastos_campos = 0.0
        ventas_campos_agri = 0.0
        gastos_campos_agri = 0.0
        ventas_campos_gana = 0.0
        gastos_campos_gana = 0.0
        rubros_venta_campos = {}
        rubros_gasto_campos = {}
        # Performance por campo
        perf_campo = {}  # {nombre: {ventas, gastos}}
        # Top cultivos
        cult_data = {}   # {cultivo: {ventas, gastos}}

        for r in rows_campos:
            estab = r["establecimiento"] or ""
            # Saltar cabeceras de reparto
            if normalize_name(estab).startswith("todos"):
                continue
            if not es_todos_campo and normalize_name(estab) != normalize_name(campo):
                continue
            monto = float(r["monto"] or 0)
            tipo = r["tipo_mov"] or ""
            rubro = r["rubro"] or "(sin rubro)"
            sector = r["sector"] or ""
            cult = r["cultivo"] or ""

            if tipo == "Venta":
                ventas_campos += monto
                rubros_venta_campos[rubro] = rubros_venta_campos.get(rubro, 0) + monto
                if sector == "Agrícola":
                    ventas_campos_agri += monto
                elif sector == "Ganadero":
                    ventas_campos_gana += monto
                perf_campo.setdefault(estab, {"ventas": 0, "gastos": 0})["ventas"] += monto
                if cult and not normalize_name(cult).startswith("todos"):
                    cult_data.setdefault(cult, {"ventas": 0, "gastos": 0})["ventas"] += monto
            elif tipo == "Gasto":
                gastos_campos += monto
                rubros_gasto_campos[rubro] = rubros_gasto_campos.get(rubro, 0) + monto
                if sector == "Agrícola":
                    gastos_campos_agri += monto
                elif sector == "Ganadero":
                    gastos_campos_gana += monto
                perf_campo.setdefault(estab, {"ventas": 0, "gastos": 0})["gastos"] += monto
                if cult and not normalize_name(cult).startswith("todos"):
                    cult_data.setdefault(cult, {"ventas": 0, "gastos": 0})["gastos"] += monto

        # Valor stock cereal de los campos
        # - patrimonial: esta campaña Y anteriores (si hay campaña), o todo si no hay
        # - ejercicio: solo la campaña seleccionada (si no hay campaña, no se filtra)
        val_stock_cereal = 0.0
        try:
            if modo_stock == "ejercicio":
                vsc_dict = self.valor_stock_cereal_por_campo(
                    fecha_hasta or dt.date.today().isoformat(),
                    campania=campania, campania_hasta=None)
            else:
                # patrimonial: si hay campaña, usar campania_hasta; si no, traer todo
                vsc_dict = self.valor_stock_cereal_por_campo(
                    fecha_hasta or dt.date.today().isoformat(),
                    campania=None, campania_hasta=campania)
            if es_todos_campo:
                val_stock_cereal = sum(vsc_dict.values())
            else:
                for k, v in vsc_dict.items():
                    if normalize_name(k) == normalize_name(campo):
                        val_stock_cereal = v
                        break
        except Exception:
            val_stock_cereal = 0.0

        # Valor stock ganado: usar última carga ≤ fecha_hasta (o hoy)
        # - patrimonial: todas las categorías
        # - ejercicio: solo Terneras y Terneros (lo nacido en el período)
        val_stock_ganado = 0.0
        cats_ganado_ejercicio = {"TERNERAS", "TERNEROS"}
        fecha_corte_stock = fecha_hasta or dt.date.today().isoformat()
        try:
            stock_rows = self.conn.execute("""
                SELECT establecimiento, categoria, cantidad, fecha
                FROM stock_ganadero WHERE fecha <= ?
                ORDER BY fecha DESC, establecimiento, categoria
            """, (fecha_corte_stock,)).fetchall()
            # Nombre oficial de establecimientos
            oficial_estab = {}
            for e in self.conn.execute("SELECT nombre FROM establecimientos"):
                oficial_estab[normalize_name(e["nombre"])] = e["nombre"]
            # Agrupar case-insensitive
            agrup_gan = {}  # (norm_e, norm_c) -> {"e_disp", "c_disp", "cant", "fecha"}
            for r in stock_rows:
                est = r["establecimiento"] or ""
                cat = r["categoria"] or ""
                key = (normalize_name(est), normalize_name(cat))
                e_disp = oficial_estab.get(normalize_name(est),
                                                est.title() if est == est.upper() and len(est) > 1 else est)
                c_disp = cat.title() if cat else cat
                if key not in agrup_gan:
                    agrup_gan[key] = {"e_disp": e_disp, "c_disp": c_disp,
                                         "cant": float(r["cantidad"] or 0),
                                         "fecha": r["fecha"]}
                else:
                    # Si es de la misma fecha, sumar (variantes mayúsculas mismo nombre)
                    if r["fecha"] == agrup_gan[key]["fecha"]:
                        agrup_gan[key]["cant"] += float(r["cantidad"] or 0)
            stock_por_estab = {}
            for info in agrup_gan.values():
                stock_por_estab.setdefault(info["e_disp"], {})[info["c_disp"]] = info["cant"]
            precios_gan = {}
            for r in self.conn.execute("SELECT * FROM categorias_mercado"):
                precios_gan[(r["categoria_stock"] or "").upper().strip()] = r["precio_animal"] or 0
            for estab, cats in stock_por_estab.items():
                if not es_todos_campo and normalize_name(estab) != normalize_name(campo):
                    continue
                for cat, cant in cats.items():
                    cat_norm = (cat or "").upper().strip()
                    # En modo ejercicio, solo Terneras/Terneros suman al valor
                    if modo_stock == "ejercicio" and cat_norm not in cats_ganado_ejercicio:
                        continue
                    pa = precios_gan.get(cat_norm, 0)
                    val_stock_ganado += cant * pa
        except Exception:
            val_stock_ganado = 0.0

        balance_campos = ventas_campos - gastos_campos
        integral_campos = balance_campos + val_stock_cereal + val_stock_ganado

        # ====================================================
        # 2. CAMPAMENTO
        # ====================================================
        q_camp = "SELECT * FROM campamento WHERE 1=1"
        params_camp = []
        wh, p = _wfechas()
        if wh:
            q_camp += " AND " + " AND ".join(wh); params_camp.extend(p)
        ventas_camp = 0.0
        gastos_camp = 0.0
        rubros_camp = {}
        # Por maquinaria: ahora trackeamos VENTAS y GASTOS por separado
        # para poder calcular el balance (rentabilidad) de cada una
        maq_camp = {}  # {nombre_maq: {"ventas": X, "gastos": Y}}
        for r in self.conn.execute(q_camp, params_camp):
            monto = float(r["monto"] or 0)
            tipo = r["tipo_mov"] or ""
            rubro = r["rubro"] or "(sin rubro)"
            maq = r["maquinaria"] or ""
            if tipo == "Venta":
                ventas_camp += monto
                if maq:
                    maq_camp.setdefault(maq, {"ventas": 0, "gastos": 0})["ventas"] += monto
            elif tipo == "Gasto":
                gastos_camp += monto
                rubros_camp[rubro] = rubros_camp.get(rubro, 0) + monto
                if maq:
                    maq_camp.setdefault(maq, {"ventas": 0, "gastos": 0})["gastos"] += monto
        balance_camp = ventas_camp - gastos_camp

        # ====================================================
        # 3. GTOS PARTICULARES
        # ====================================================
        q_gp = "SELECT * FROM gtos_particulares WHERE 1=1"
        params_gp = []
        wh, p = _wfechas()
        if wh:
            q_gp += " AND " + " AND ".join(wh); params_gp.extend(p)
        ventas_gp = 0.0
        gastos_gp = 0.0
        rubros_gp = {}
        for r in self.conn.execute(q_gp, params_gp):
            monto = float(r["monto"] or 0)
            tipo = r["tipo_mov"] or ""
            rubro = r["rubro"] or "(sin rubro)"
            if tipo == "Venta":
                ventas_gp += monto
            elif tipo == "Gasto":
                gastos_gp += monto
                rubros_gp[rubro] = rubros_gp.get(rubro, 0) + monto
        balance_gp = ventas_gp - gastos_gp

        # ====================================================
        # CONSOLIDADO
        # ====================================================
        total_ventas = ventas_campos + ventas_camp + ventas_gp
        total_gastos = gastos_campos + gastos_camp + gastos_gp
        balance_total = total_ventas - total_gastos
        integral_total = balance_total + val_stock_cereal + val_stock_ganado

        # ====================================================
        # TOPS CONSOLIDADOS
        # ====================================================
        # Rubros gasto consolidado (con fuente)
        rubros_gasto_consol = []
        for k, v in rubros_gasto_campos.items():
            rubros_gasto_consol.append({"fuente": "Campos", "rubro": k, "monto": v})
        for k, v in rubros_camp.items():
            rubros_gasto_consol.append({"fuente": "Campamento", "rubro": k, "monto": v})
        for k, v in rubros_gp.items():
            rubros_gasto_consol.append({"fuente": "Gtos Particulares", "rubro": k, "monto": v})
        rubros_gasto_consol.sort(key=lambda x: -x["monto"])
        for r in rubros_gasto_consol:
            r["pct"] = (r["monto"] / total_gastos * 100) if total_gastos > 0 else 0

        # Rubros venta consolidado (en general las ventas son solo de Campos pero por las dudas)
        rubros_venta_consol = []
        for k, v in rubros_venta_campos.items():
            rubros_venta_consol.append({"fuente": "Campos", "rubro": k, "monto": v})
        rubros_venta_consol.sort(key=lambda x: -x["monto"])
        for r in rubros_venta_consol:
            r["pct"] = (r["monto"] / total_ventas * 100) if total_ventas > 0 else 0

        # Performance por campo
        perf_list = []
        for nombre, d in perf_campo.items():
            v = d["ventas"]; g = d["gastos"]
            bal = v - g
            margen = (bal / v * 100) if v > 0 else 0
            perf_list.append({"campo": nombre, "ventas": v, "gastos": g,
                              "balance": bal, "margen_pct": margen})
        perf_list.sort(key=lambda x: -x["balance"])

        # Top cultivos
        cult_list = []
        for nombre, d in cult_data.items():
            v = d["ventas"]; g = d["gastos"]
            bal = v - g
            cult_list.append({"cultivo": nombre, "ventas": v, "gastos": g, "balance": bal})
        cult_list.sort(key=lambda x: -x["balance"])

        # Top maquinarias: ahora con ventas, gastos y balance (rentabilidad)
        # Ordenado por balance descendente (más rentable primero)
        maq_list = []
        for nombre, d in maq_camp.items():
            v = d["ventas"]
            g = d["gastos"]
            bal = v - g
            maq_list.append({
                "maquinaria": nombre,
                "ventas": v,
                "gastos": g,
                "balance": bal,
                "monto": g,  # compatibilidad con código viejo que esperaba "monto"
            })
        maq_list.sort(key=lambda x: -x["balance"])

        # ====================================================
        # ALERTAS Y EFICIENCIAS
        # ====================================================
        alertas = []
        eficiencias = []

        # Alertas
        if balance_campos < 0:
            alertas.append(
                f"❌ El balance operativo de Campos es NEGATIVO ({fmt_money(balance_campos)}). "
                "Los gastos están superando a las ventas.")
        for pc in perf_list:
            if pc["balance"] < 0 and pc["ventas"] > 0:
                alertas.append(
                    f"❌ El campo '{pc['campo']}' está con balance NEGATIVO "
                    f"({fmt_money(pc['balance'])}, margen {pc['margen_pct']:.1f}%).")
        if total_gastos > 0:
            pct_gp_total = (gastos_gp / total_gastos * 100)
            if pct_gp_total > 30:
                alertas.append(
                    f"⚠ Los Gastos Particulares representan {pct_gp_total:.1f}% del total de gastos. "
                    "Suelen recomendarse niveles menores al 30%.")
            pct_camp_total = (gastos_camp / total_gastos * 100)
            if pct_camp_total > 40:
                alertas.append(
                    f"⚠ Los gastos de Campamento representan {pct_camp_total:.1f}% del total. "
                    "Revisar si hay rubros optimizables.")

        # Stock ganado sin precio
        if val_stock_ganado == 0 and stock_por_estab:
            alertas.append(
                "⚠ Hay stock ganado cargado pero no se valoró (faltan precios en 'Precios Ganado').")

        # Sub-stock bolsones en rojo
        try:
            subs = self.sbm_stock_por_bolson(fecha_hasta=fecha_hasta)
            negs = [s for s in subs if s["sub_stock"] < 0]
            if negs:
                alertas.append(
                    f"🔴 {len(negs)} bolsón/es con sub-stock NEGATIVO. "
                    "Revisá la pestaña 'Stock Cereal (Libro)'.")
        except Exception:
            pass

        # Cultivos con margen bajo
        for c in cult_list:
            if c["ventas"] > 0:
                margen = (c["balance"] / c["ventas"] * 100)
                if margen < 10 and c["ventas"] > 0:
                    alertas.append(
                        f"⚠ El cultivo '{c['cultivo']}' tiene margen bajo ({margen:.1f}%): "
                        f"ventas {fmt_money(c['ventas'])}, gastos {fmt_money(c['gastos'])}.")
                    break  # solo el peor

        # Arrendamientos altos
        arr = rubros_gasto_campos.get("Arrendamiento", 0)
        if arr > 0 and ventas_campos > 0:
            pct_arr = (arr / ventas_campos * 100)
            if pct_arr > 35:
                alertas.append(
                    f"⚠ Los arrendamientos representan {pct_arr:.1f}% de las ventas de Campos. "
                    "Suele ser sano mantenerlo bajo 35%.")

        # Eficiencias
        if balance_campos > 0 and ventas_campos > 0:
            margen_c = (balance_campos / ventas_campos * 100)
            if margen_c > 30:
                eficiencias.append(
                    f"✅ Excelente margen operativo en Campos: {margen_c:.1f}% sobre ventas.")
            elif margen_c > 15:
                eficiencias.append(
                    f"✅ Buen margen operativo en Campos: {margen_c:.1f}% sobre ventas.")

        if perf_list:
            mejor = perf_list[0]
            if mejor["balance"] > 0:
                eficiencias.append(
                    f"🏆 Mejor campo del período: '{mejor['campo']}' "
                    f"con balance de {fmt_money(mejor['balance'])} "
                    f"(margen {mejor['margen_pct']:.1f}%).")

        if cult_list:
            mejor_cult = cult_list[0]
            if mejor_cult["balance"] > 0:
                margen = (mejor_cult["balance"] / mejor_cult["ventas"] * 100) if mejor_cult["ventas"] > 0 else 0
                eficiencias.append(
                    f"🌾 Cultivo más rentable: '{mejor_cult['cultivo']}' "
                    f"con balance de {fmt_money(mejor_cult['balance'])} "
                    f"({margen:.1f}% de margen).")

        if val_stock_cereal > 0:
            eficiencias.append(
                f"📦 Tenés stock cereal valuado en {fmt_money(val_stock_cereal)} "
                "como reserva para futuras ventas.")
        if val_stock_ganado > 0:
            eficiencias.append(
                f"🐄 Tenés stock ganado valuado en {fmt_money(val_stock_ganado)}.")

        if integral_total > 0:
            eficiencias.append(
                f"💰 Balance INTEGRAL CONSOLIDADO POSITIVO de {fmt_money(integral_total)} "
                "(operativo + valor de stocks).")

        return {
            "filtros": {
                "desde": fecha_desde, "hasta": fecha_hasta,
                "campania": campania, "campo": campo or "TODOS",
                "modo_stock": modo_stock,
            },
            "campos": {
                "ventas": ventas_campos,
                "gastos": gastos_campos,
                "ventas_agricola": ventas_campos_agri,
                "gastos_agricola": gastos_campos_agri,
                "ventas_ganadero": ventas_campos_gana,
                "gastos_ganadero": gastos_campos_gana,
                "balance": balance_campos,
                "val_stock_cereal": val_stock_cereal,
                "val_stock_ganado": val_stock_ganado,
                "integral": integral_campos,
            },
            "campamento": {
                "ventas": ventas_camp,
                "gastos": gastos_camp,
                "balance": balance_camp,
                "top_rubros": sorted(
                    [{"rubro": k, "monto": v} for k, v in rubros_camp.items()],
                    key=lambda x: -x["monto"]),
                "top_maquinarias": maq_list,
            },
            "gtos_particulares": {
                "ventas": ventas_gp,
                "gastos": gastos_gp,
                "balance": balance_gp,
                "top_rubros": sorted(
                    [{"rubro": k, "monto": v} for k, v in rubros_gp.items()],
                    key=lambda x: -x["monto"]),
            },
            "consolidado": {
                "total_ventas": total_ventas,
                "total_gastos": total_gastos,
                "balance_total": balance_total,
                "val_stock_cereal": val_stock_cereal,
                "val_stock_ganado": val_stock_ganado,
                "integral_total": integral_total,
            },
            "top_rubros_gasto": rubros_gasto_consol,
            "top_rubros_venta": rubros_venta_consol,
            "performance_campos": perf_list,
            "top_cultivos": cult_list,
            "top_maquinarias": maq_list,
            "alertas": alertas,
            "eficiencias": eficiencias,
        }

    def diagnostico_ventas_cereal(self, campania, cultivo):
        """Devuelve info detallada de las ventas de cereal para diagnosticar
        por qué algunas ventas no se computan en el stock."""
        rows = self.conn.execute("""
            SELECT id, fecha, establecimiento, sector, cultivo, tipo_mov, rubro,
                   unidades, monto, link_id
            FROM campos
            WHERE campania=?
            ORDER BY fecha DESC, id DESC
        """, (campania,))
        cult_norm = normalize_name(cultivo)
        resultado = []
        for r in rows:
            d = dict(r)
            d["_motivo"] = []
            if (d.get("tipo_mov") or "") != "Venta":
                d["_motivo"].append(f"tipo_mov='{d.get('tipo_mov')}' (esperado: Venta)")
            if (d.get("rubro") or "") != "Cereal":
                d["_motivo"].append(f"rubro='{d.get('rubro')}' (esperado: Cereal)")
            if normalize_name(d.get("cultivo") or "") != cult_norm:
                d["_motivo"].append(f"cultivo='{d.get('cultivo')}' (esperado: {cultivo})")
            if (d.get("establecimiento") or "").upper().startswith("TODOS"):
                d["_motivo"].append("establecimiento es TODOS (no se cuenta)")
            if not d.get("unidades") or float(d.get("unidades") or 0) <= 0:
                d["_motivo"].append(f"unidades vacío o cero ({d.get('unidades')})")
            d["_cuenta"] = len(d["_motivo"]) == 0
            resultado.append(d)
        return resultado

    def cultivos_con_stock(self, campania):
        """Lista cultivos cargados en stock_cereal para una campaña."""
        rows = self.conn.execute("""
            SELECT DISTINCT cultivo FROM stock_cereal
            WHERE campania=? ORDER BY cultivo
        """, (campania,))
        return [r["cultivo"] for r in rows]

    def campanias_con_stock(self):
        """Lista campañas que tengan filas en stock_cereal."""
        rows = self.conn.execute("""
            SELECT DISTINCT campania FROM stock_cereal ORDER BY campania DESC
        """)
        return [r["campania"] for r in rows]

    def listar(self, tabla, filtros=None, orden="fecha DESC, id DESC"):
        q = f"SELECT * FROM {tabla}"
        params = []
        if filtros:
            wh = []
            for k, v in filtros.items():
                if v not in (None, "", "Todos"):
                    if k.endswith("_desde"):
                        wh.append("fecha >= ?")
                    elif k.endswith("_hasta"):
                        wh.append("fecha <= ?")
                    else:
                        wh.append(f"{k} = ?")
                    params.append(v)
            if wh:
                q += " WHERE " + " AND ".join(wh)
        q += f" ORDER BY {orden}"
        return [dict(r) for r in self.conn.execute(q, params)]

    # ==================== LIBRO DE IVA ====================
    # ---- Proveedores ----
    def iva_prov_listar(self, solo_activos=True):
        q = "SELECT * FROM iva_proveedores"
        if solo_activos:
            q += " WHERE activo=1"
        q += " ORDER BY nombre"
        return [dict(r) for r in self.conn.execute(q)]

    def iva_prov_get_por_nombre(self, nombre):
        r = self.conn.execute(
            "SELECT * FROM iva_proveedores WHERE nombre=? LIMIT 1", (nombre,)).fetchone()
        return dict(r) if r else None

    def iva_prov_insertar(self, nombre, cuit=None, cond_iva=None, codigo=None):
        cur = self.conn.execute(
            "INSERT INTO iva_proveedores (nombre, cuit, cond_iva, codigo) VALUES (?,?,?,?)",
            (nombre, cuit, cond_iva, codigo))
        self.conn.commit()
        return cur.lastrowid

    def iva_prov_upsert(self, nombre, cuit=None, cond_iva=None, codigo=None):
        """Inserta si no existe (por nombre); si existe, actualiza CUIT/cond/código."""
        ex = self.iva_prov_get_por_nombre(nombre)
        if ex:
            self.conn.execute(
                "UPDATE iva_proveedores SET cuit=?, cond_iva=?, codigo=? WHERE id=?",
                (cuit or ex.get("cuit"), cond_iva or ex.get("cond_iva"),
                 codigo if codigo is not None else ex.get("codigo"), ex["id"]))
            self.conn.commit()
            return ex["id"]
        return self.iva_prov_insertar(nombre, cuit, cond_iva, codigo)

    # ---- IVA Compras ----
    _IVA_COMPRAS_COLS = ["anio","mes","fecha","tipo_comp","comprobante","proveedor","cuit","cond_iva",
        "rub","rubro2","neto_27","neto_21","neto_105","neto_monot",
        "exc_importe","exc_lts_gasoil","exc_imp_gasoil","iva_27","iva_21","iva_105",
        "imp_total","ret_iva","ret_iibb","reparto_json","observaciones"]

    def iva_compras_insertar(self, **campos):
        cols = [c for c in self._IVA_COMPRAS_COLS if c in campos]
        ph = ", ".join("?" for _ in cols)
        vals = [campos[c] for c in cols]
        cur = self.conn.execute(
            f"INSERT INTO iva_compras ({', '.join(cols)}) VALUES ({ph})", vals)
        self.conn.commit()
        return cur.lastrowid

    def iva_compras_actualizar(self, rid, **campos):
        cols = [c for c in self._IVA_COMPRAS_COLS if c in campos]
        if not cols:
            return
        sets = ", ".join(f"{c}=?" for c in cols)
        vals = [campos[c] for c in cols] + [rid]
        self.conn.execute(f"UPDATE iva_compras SET {sets} WHERE id=?", vals)
        self.conn.commit()

    def iva_compras_get(self, rid):
        r = self.conn.execute("SELECT * FROM iva_compras WHERE id=?", (rid,)).fetchone()
        return dict(r) if r else None

    def iva_compras_listar(self, anio=None, mes=None):
        q = "SELECT * FROM iva_compras"
        wh, params = [], []
        if anio:
            wh.append("anio=?"); params.append(int(anio))
        if mes:
            wh.append("mes=?"); params.append(int(mes))
        if wh:
            q += " WHERE " + " AND ".join(wh)
        q += " ORDER BY fecha, id"
        return [dict(r) for r in self.conn.execute(q, params)]

    def iva_compras_eliminar(self, rid):
        self.conn.execute("DELETE FROM iva_compras WHERE id=?", (rid,))
        self.conn.commit()

    def iva_compras_anios(self):
        rows = self.conn.execute("SELECT DISTINCT anio FROM iva_compras ORDER BY anio DESC").fetchall()
        return [r["anio"] for r in rows]

    # ---- IVA Ventas ----
    _IVA_VENTAS_COLS = ["anio","mes","fecha","tipo_comp","comprobante","proveedor","cuit","cond_iva",
        "rub","rubro2","neto_21","neto_105","exc_importe","exc_lts_gasoil","exc_imp_gasoil",
        "iva_21","iva_105","imp_total","ret_gan","ret_iva","ret_perc_iibb",
        "reparto_json","observaciones"]

    def iva_ventas_insertar(self, **campos):
        cols = [c for c in self._IVA_VENTAS_COLS if c in campos]
        ph = ", ".join("?" for _ in cols)
        vals = [campos[c] for c in cols]
        cur = self.conn.execute(
            f"INSERT INTO iva_ventas ({', '.join(cols)}) VALUES ({ph})", vals)
        self.conn.commit()
        return cur.lastrowid

    def iva_ventas_actualizar(self, rid, **campos):
        cols = [c for c in self._IVA_VENTAS_COLS if c in campos]
        if not cols:
            return
        sets = ", ".join(f"{c}=?" for c in cols)
        vals = [campos[c] for c in cols] + [rid]
        self.conn.execute(f"UPDATE iva_ventas SET {sets} WHERE id=?", vals)
        self.conn.commit()

    def iva_ventas_get(self, rid):
        r = self.conn.execute("SELECT * FROM iva_ventas WHERE id=?", (rid,)).fetchone()
        return dict(r) if r else None

    def iva_ventas_listar(self, anio=None, mes=None):
        q = "SELECT * FROM iva_ventas"
        wh, params = [], []
        if anio:
            wh.append("anio=?"); params.append(int(anio))
        if mes:
            wh.append("mes=?"); params.append(int(mes))
        if wh:
            q += " WHERE " + " AND ".join(wh)
        q += " ORDER BY fecha, id"
        return [dict(r) for r in self.conn.execute(q, params)]

    def iva_ventas_eliminar(self, rid):
        self.conn.execute("DELETE FROM iva_ventas WHERE id=?", (rid,))
        self.conn.commit()

    def iva_ventas_anios(self):
        rows = self.conn.execute("SELECT DISTINCT anio FROM iva_ventas ORDER BY anio DESC").fetchall()
        return [r["anio"] for r in rows]

    # ---- Alícuota de gas-oil por mes ----
    def iva_gasoil_get(self, anio, mes):
        r = self.conn.execute(
            "SELECT valor_litro FROM iva_gasoil_alicuota WHERE anio=? AND mes=?",
            (int(anio), int(mes))).fetchone()
        return float(r["valor_litro"]) if r else 0.0

    def iva_gasoil_set(self, anio, mes, valor_litro):
        self.conn.execute(
            "INSERT INTO iva_gasoil_alicuota (anio, mes, valor_litro) VALUES (?,?,?) "
            "ON CONFLICT(anio, mes) DO UPDATE SET valor_litro=excluded.valor_litro",
            (int(anio), int(mes), float(valor_litro)))
        self.conn.commit()

    # ---- Resumen ARCA: totales por alícuota separando FA+ND de NC ----
    def iva_resumen_arca(self, tipo, anio, mes=None):
        """Calcula el resumen para ARCA de 'compras' o 'ventas'.
        Devuelve un dict con:
          'facturas': {alicuota: {'neto':x, 'fiscal':y}, ...}  (FA+ND)
          'nc':       {alicuota: {'neto':x, 'fiscal':y}, ...}  (Notas de Crédito)
          'tot_fac':  {'neto':, 'exento':, 'fiscal':}
          'tot_nc':   {'neto':, 'exento':, 'fiscal':}
          'monotributo': x   (solo compras)
        El 'fiscal' es Débito (ventas) o Crédito (compras).
        Las NC se agrupan aparte; sus montos se toman en positivo (el signo
        lo aplica la determinación del impuesto)."""
        if tipo == "compras":
            filas = self.iva_compras_listar(anio=anio, mes=mes)
            alics = [("27%", "neto_27", "iva_27"), ("21%", "neto_21", "iva_21"),
                     ("10,5%", "neto_105", "iva_105")]
        else:
            filas = self.iva_ventas_listar(anio=anio, mes=mes)
            alics = [("21%", "neto_21", "iva_21"), ("10,5%", "neto_105", "iva_105")]

        fac = {}; nc = {}
        tot_fac = {"neto": 0.0, "exento": 0.0, "fiscal": 0.0}
        tot_nc = {"neto": 0.0, "exento": 0.0, "fiscal": 0.0}
        monotributo = 0.0

        for f in filas:
            es_nc = (f.get("tipo_comp") or "").strip().upper() == "NC"
            destino = nc if es_nc else fac
            tot = tot_nc if es_nc else tot_fac
            for label, nkey, ikey in alics:
                neto = abs(float(f.get(nkey) or 0))
                iva = abs(float(f.get(ikey) or 0))
                if neto or iva:
                    if label not in destino:
                        destino[label] = {"neto": 0.0, "fiscal": 0.0}
                    destino[label]["neto"] += neto
                    destino[label]["fiscal"] += iva
                    tot["neto"] += neto
                    tot["fiscal"] += iva
            tot["exento"] += abs(float(f.get("exc_importe") or 0))
            if tipo == "compras":
                monotributo += abs(float(f.get("neto_monot") or 0))

        return {"facturas": fac, "nc": nc, "tot_fac": tot_fac,
                "tot_nc": tot_nc, "monotributo": monotributo}

    # ---- Saldo técnico a favor del período anterior (manual, editable) ----
    def iva_saldo_get(self, anio, mes, clave):
        """clave: 'saldo_anterior' o 'libre_disp'. Devuelve el valor guardado o 0."""
        r = self.conn.execute(
            "SELECT valor FROM config WHERE clave=?",
            (f"iva_saldo_{clave}_{anio}_{mes}",)).fetchone()
        try:
            return float(r["valor"]) if r and r["valor"] not in (None, "") else 0.0
        except Exception:
            return 0.0

    def iva_saldo_set(self, anio, mes, clave, valor):
        self.set_config(f"iva_saldo_{clave}_{anio}_{mes}", str(valor))


