# UTILIDADES
# ============================================================
def fmt_money(v):
    try:
        v = float(v or 0)
    except Exception:
        return "$ 0,00"
    s = f"{v:,.2f}"
    # Convertir formato US (1,234.56) a AR (1.234,56)
    s = s.replace(",", "X").replace(".", ",").replace("X", ".")
    return f"$ {s}"

def parse_money(s):
    if s is None: return 0.0
    s = str(s).strip().replace("$", "").replace(" ", "")
    if not s: return 0.0
    # Aceptar formato AR (1.234,56) o US (1234.56)
    if "," in s and "." in s:
        # asumir AR
        s = s.replace(".", "").replace(",", ".")
    elif "," in s:
        s = s.replace(",", ".")
    try:
        return float(s)
    except Exception:
        return 0.0

def parse_fecha(s):
    """Acepta dd/mm/aaaa o aaaa-mm-dd. Devuelve string ISO aaaa-mm-dd."""
    if not s:
        return None
    s = s.strip()
    for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y", "%d/%m/%y"):
        try:
            return dt.datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass
    return None

def fmt_fecha(iso):
    if not iso: return ""
    try:
        return dt.datetime.strptime(iso, "%Y-%m-%d").strftime("%d/%m/%Y")
    except Exception:
        return iso

def hoy_iso():
    return dt.date.today().strftime("%Y-%m-%d")


def crear_fecha_widget(parent, valor_inicial=None, width=14, permitir_vacio=False):
    """Crea un widget de selección de fecha.

    Si tkcalendar está disponible: DateEntry con calendario popup al hacer clic.
    Si no: Entry normal con formato dd/mm/aaaa.

    Args:
        parent: widget padre.
        valor_inicial: string en formato ISO 'aaaa-mm-dd' o 'dd/mm/aaaa', o None.
        width: ancho del widget en caracteres.
        permitir_vacio: si True, el campo puede quedar vacío (para filtros tipo
                        "Desde/Hasta"). Si False, se precarga con la fecha de hoy.

    Devuelve:
        (widget, getter, setter) donde:
          - widget: el widget en sí (para hacer .grid/.pack).
          - getter(): devuelve la fecha en formato ISO 'aaaa-mm-dd' o '' si vacío.
          - setter(iso_o_dmy): setea la fecha desde un string ISO o dd/mm/aaaa.
    """
    # Normalizar valor inicial a date o None
    fecha_inicial = None
    if valor_inicial:
        iso = parse_fecha(valor_inicial) if "/" in str(valor_inicial) or "-" in str(valor_inicial) else None
        if iso:
            try:
                fecha_inicial = dt.datetime.strptime(iso, "%Y-%m-%d").date()
            except Exception:
                fecha_inicial = None

    if TKCALENDAR_OK:
        # Para campos "vacíos permitidos" (filtros): empezamos sin fecha.
        # tkcalendar siempre exige una fecha interna, pero podemos vaciar el Entry.
        kwargs = dict(
            width=width,
            font=(FONT_FAMILY, 10),
            date_pattern="dd/mm/yyyy",
            locale="es_AR",
            background=COLORS["primary"],
            foreground="white",
            bordercolor=COLORS["border"],
            headersbackground=COLORS["primary"],
            headersforeground="white",
            normalbackground="white",
            normalforeground=COLORS["text"],
            weekendbackground="white",
            weekendforeground=COLORS["text"],
            othermonthforeground="#AAAAAA",
            othermonthbackground="#F0F0F0",
            othermonthwebackground="#F0F0F0",
            othermonthweforeground="#AAAAAA",
            selectbackground=COLORS["accent"],
            selectforeground="white",
        )
        try:
            widget = DateEntry(parent, **kwargs)
        except Exception:
            # Locale es_AR puede no estar disponible: reintentar sin locale
            kwargs.pop("locale", None)
            try:
                widget = DateEntry(parent, **kwargs)
            except Exception:
                # Algún color avanzado puede no soportarse en cierta versión:
                # reintentar con kwargs mínimos
                widget = DateEntry(parent, width=width, font=(FONT_FAMILY, 10),
                                    date_pattern="dd/mm/yyyy")

        # Vaciar el campo si permite vacío y no había valor inicial
        if permitir_vacio and fecha_inicial is None:
            widget.delete(0, END)
        elif fecha_inicial is not None:
            widget.set_date(fecha_inicial)
        # Si no permite vacío y no hay valor inicial: queda con la fecha de hoy (default)

        # Cuando permitir_vacio=True, queremos que el campo se quede VACÍO
        # aunque el usuario haga foco sin elegir nada. tkcalendar tiene la
        # tendencia a "rellenar con hoy" al recibir foco o al perderlo.
        # Para evitarlo, mantenemos una bandera "el usuario eligió una fecha"
        # y, si está apagada, vaciamos el campo en FocusOut.
        if permitir_vacio:
            widget._user_picked = (fecha_inicial is not None)
            def _on_pick(event=None):
                widget._user_picked = True
            def _on_focus_out(event=None):
                # Si el usuario nunca eligió, asegurar campo vacío
                if not widget._user_picked:
                    try: widget.delete(0, END)
                    except Exception: pass
            widget.bind("<<DateEntrySelected>>", _on_pick, add="+")
            # Si el usuario tipea algo manualmente también lo consideramos elegido
            def _on_keyrelease(event=None):
                txt = widget.get().strip()
                if txt:
                    widget._user_picked = True
                else:
                    widget._user_picked = False
            widget.bind("<KeyRelease>", _on_keyrelease, add="+")
            widget.bind("<FocusOut>", _on_focus_out, add="+")

        def _get():
            # Si permitimos vacío y el usuario no eligió, devolver vacío
            # aunque tkcalendar haya rellenado con la fecha de hoy.
            if permitir_vacio and not getattr(widget, "_user_picked", False):
                return ""
            txt = widget.get().strip()
            if not txt:
                return ""
            iso = parse_fecha(txt)
            return iso or ""

        def _set(val):
            if not val:
                widget.delete(0, END)
                if permitir_vacio:
                    widget._user_picked = False
                return
            iso = parse_fecha(val)
            if iso:
                try:
                    d = dt.datetime.strptime(iso, "%Y-%m-%d").date()
                    widget.set_date(d)
                    if permitir_vacio:
                        widget._user_picked = True
                    return
                except Exception:
                    pass
            # Si no se pudo parsear: setear texto directo
            try:
                widget.delete(0, END)
                widget.insert(0, val)
                if permitir_vacio:
                    widget._user_picked = bool(val)
            except Exception:
                pass

        return widget, _get, _set

    # Fallback: Entry normal
    var = StringVar()
    if fecha_inicial is not None:
        var.set(fecha_inicial.strftime("%d/%m/%Y"))
    elif not permitir_vacio:
        var.set(dt.date.today().strftime("%d/%m/%Y"))
    widget = Entry(parent, textvariable=var, width=width, font=(FONT_FAMILY, 10))

    def _get():
        return parse_fecha(var.get()) or ""

    def _set(val):
        if not val:
            var.set("")
            return
        iso = parse_fecha(val)
        if iso:
            try:
                d = dt.datetime.strptime(iso, "%Y-%m-%d").date()
                var.set(d.strftime("%d/%m/%Y"))
                return
            except Exception:
                pass
        var.set(str(val))

    # Para compatibilidad: si alguien quiere acceder al StringVar
    widget._date_var = var
    return widget, _get, _set

def recordar_geometria(win, db, clave, geom_default="580x440"):
    """Hace que una ventana Toplevel recuerde su tamaño/posición entre sesiones.

    Lee la última geometría guardada en la tabla config (bajo `clave`).
    Si no hay nada guardado, usa `geom_default`.
    Al cerrarse la ventana (X, destroy() o Cancelar), guarda la geometría actual.

    Args:
        win: la Toplevel.
        db: instancia de DB (con get_config/set_config).
        clave: nombre único de la clave en config, ej. "win_geom_cheque".
        geom_default: geometría inicial si no hay guardada.
    """
    geom_guardada = db.get_config(clave, default=None)
    if geom_guardada:
        try:
            win.geometry(geom_guardada)
        except Exception:
            win.geometry(geom_default)
    else:
        win.geometry(geom_default)

    def _guardar(_event=None):
        try:
            g = win.winfo_geometry()
            if "x" in g:
                db.set_config(clave, g)
        except Exception:
            pass

    # Cuando se cierra con la X
    def _on_close():
        _guardar()
        win.destroy()
    win.protocol("WM_DELETE_WINDOW", _on_close)
    # Cuando se destruye por código (destroy())
    win.bind("<Destroy>",
              lambda e: _guardar() if e.widget is win else None,
              add="+")



def normalize_name(s):
    """Devuelve una clave normalizada (sin tildes, sin mayúsculas, sin espacios extra)
    para hacer match entre nombres como 'EL RINCON' y 'El Rincón'."""
    if not s: return ""
    s = str(s).strip()
    # Sacar tildes
    s = unicodedata.normalize("NFD", s)
    s = "".join(c for c in s if unicodedata.category(c) != "Mn")
    # Minúsculas y espacios colapsados
    s = re.sub(r"\s+", " ", s).lower().strip()
    return s


def es_ubicacion_bolson(ubicacion):
    """Devuelve True si la ubicación del depósito contiene la palabra 'bolson'
    (insensible a tildes y mayúsculas). Detecta variantes: 'Bolsón', 'BOLSON',
    'Bolson 1', 'Bolsón Norte', 'Tres Bolsones', etc."""
    if not ubicacion:
        return False
    return "bolson" in normalize_name(ubicacion)


