# ============================================================
# CARGA DE CSV DE STOCK GANADERO
# ============================================================
class StockLoader:
    """Carga el CSV exportado por la app Stock Ganadero (web)."""

    @staticmethod
    def cargar_csv(path):
        """Lee un CSV y devuelve lista de dicts con fecha, establecimiento, categoria, cantidad.

        Soporta varios formatos de columnas comunes:
          - fecha / Fecha / Stock al
          - establecimiento / Campo / Establecimiento
          - categoria / Categoría / Categoria
          - cantidad / Stock / Saldo / Cabezas
        """
        if not os.path.exists(path):
            raise FileNotFoundError(f"No se encontró el archivo: {path}")
        # Detectar encoding y delimitador
        for enc in ("utf-8-sig", "utf-8", "latin-1", "cp1252"):
            try:
                with open(path, "r", encoding=enc, newline="") as f:
                    sample = f.read(2048)
                    f.seek(0)
                    try:
                        dialect = csv.Sniffer().sniff(sample, delimiters=",;|\t")
                    except csv.Error:
                        dialect = csv.excel
                    reader = csv.DictReader(f, dialect=dialect)
                    rows = list(reader)
                break
            except UnicodeDecodeError:
                continue
        else:
            raise RuntimeError("No se pudo leer el CSV (encoding no detectado).")

        if not rows:
            return []

        # Mapear columnas
        cols = {c.lower().strip(): c for c in rows[0].keys() if c}

        def find_col(*candidatos):
            for cand in candidatos:
                if cand in cols:
                    return cols[cand]
            # Buscar match parcial
            for cand in candidatos:
                for k, v in cols.items():
                    if cand in k:
                        return v
            return None

        col_fecha = find_col("fecha", "stock al", "stock_al", "date")
        col_estab = find_col("establecimiento", "campo", "estancia")
        col_cat   = find_col("categoria", "categoría", "category")
        col_cant  = find_col("cantidad", "stock", "saldo", "cabezas", "saldo final", "total")

        if not (col_estab and col_cat and col_cant):
            raise RuntimeError(
                "El CSV no tiene las columnas esperadas. "
                "Se necesitan al menos: Establecimiento/Campo, Categoría, Cantidad/Stock."
            )

        out = []
        for r in rows:
            estab = (r.get(col_estab) or "").strip()
            cat = (r.get(col_cat) or "").strip()
            cant_raw = (r.get(col_cant) or "0").strip()
            # Sacar + y - de números tipo "+105"
            cant_raw = cant_raw.replace("+", "").replace(" ", "")
            if "," in cant_raw and "." in cant_raw:
                cant_raw = cant_raw.replace(".", "").replace(",", ".")
            elif "," in cant_raw:
                cant_raw = cant_raw.replace(",", ".")
            try:
                cant = int(float(cant_raw))
            except ValueError:
                cant = 0
            fecha = (r.get(col_fecha) or "").strip() if col_fecha else ""
            fecha_iso = parse_fecha(fecha) if fecha else None
            if not estab or not cat:
                continue
            out.append({
                "fecha": fecha_iso,
                "establecimiento": estab,
                "categoria": cat.upper(),
                "cantidad": cant,
            })
        return out


# ============================================================
# AGRUPACIONES DE CAMPOS - REPARTO PROPORCIONAL
# ============================================================
class AgrupacionRepartidor:
    """Aplica reparto proporcional entre campos agrupados.

    Reglas:
      - Solo movimientos del campo PRINCIPAL con Sector=Ganadero y Rubro != Arrendamiento
        se reparten entre todos los campos del grupo.
      - El stock cargado en cualquier campo del grupo se reparte también.
      - Arrendamientos NUNCA se reparten (cada campo carga el propio).
      - Movimientos en otros campos del grupo (Badino, Parras) que NO sean
        el principal quedan tal cual (no se redistribuyen).
    """

    @staticmethod
    def listar_agrupaciones(db):
        """Devuelve list[dict] con todas las agrupaciones y sus campos."""
        out = []
        for ag in db.conn.execute("SELECT * FROM agrupaciones ORDER BY id"):
            campos = list(db.conn.execute(
                "SELECT * FROM agrupacion_campos WHERE agrupacion_id=?",
                (ag["id"],)))
            out.append({
                "id": ag["id"],
                "nombre": ag["nombre"],
                "campo_principal": ag["campo_principal"],
                "campos": [{"establecimiento": c["establecimiento"],
                            "has_totales": c["has_totales"]} for c in campos],
            })
        return out

    @staticmethod
    def has_por_campania(db, agrupacion_id, campania):
        """Devuelve dict {establecimiento: {totales, agricolas, ganaderas}}
        para los campos de una agrupación, leyendo de has_campania (tabla global).
        """
        # Campos del grupo
        campos = [c["establecimiento"] for c in db.conn.execute(
            "SELECT establecimiento FROM agrupacion_campos WHERE agrupacion_id=?",
            (agrupacion_id,))]
        out = {}
        for e in campos:
            # Leer de la tabla global
            row = db.conn.execute("""
                SELECT has_totales, has_agricolas FROM has_campania
                WHERE campania=? AND establecimiento=?
            """, (campania, e)).fetchone()
            if row:
                tot = row["has_totales"] or 0
                agr = row["has_agricolas"] or 0
            else:
                tot = agr = 0
            out[e] = {
                "totales": tot,
                "agricolas": agr,
                "ganaderas": max(0, tot - agr),
            }
        return out

    @staticmethod
    def has_global_campania(db, campania):
        """Devuelve dict {establecimiento: {totales, agricolas, ganaderas}}
        de TODOS los campos cargados para esa campaña."""
        out = {}
        for c in db.conn.execute("""
            SELECT establecimiento, has_totales, has_agricolas
            FROM has_campania WHERE campania=?
        """, (campania,)):
            tot = c["has_totales"] or 0
            agr = c["has_agricolas"] or 0
            out[c["establecimiento"]] = {
                "totales": tot,
                "agricolas": agr,
                "ganaderas": max(0, tot - agr),
            }
        return out

    @staticmethod
    def proporciones_globales(has_global, sector):
        """Devuelve dict {establecimiento: proporcion (0..1)} para reparto global.

        sector: 'Agrícola' usa has agrícolas, 'Ganadero' usa has ganaderas.
        Si no hay totales válidos, devuelve {} (sin reparto).
        """
        if not has_global:
            return {}
        col = "agricolas" if sector == "Agrícola" else "ganaderas"
        total = sum(d[col] for d in has_global.values())
        if total <= 0:
            return {}
        return {e: d[col] / total for e, d in has_global.items()}

    @staticmethod
    def proporciones(has_dict):
        """Devuelve dict {establecimiento: proporcion (0..1)} en base a has ganaderas."""
        total_gan = sum(d["ganaderas"] for d in has_dict.values())
        if total_gan <= 0:
            # Sin info válida: reparto igualitario
            n = len(has_dict)
            if n == 0:
                return {}
            return {e: 1.0 / n for e in has_dict}
        return {e: d["ganaderas"] / total_gan for e, d in has_dict.items()}

    @staticmethod
    def es_arrendamiento(rubro):
        """¿El rubro es arrendamiento? (no se reparte)"""
        if not rubro: return False
        return "arrendamiento" in rubro.lower()

    @staticmethod
    def encontrar_agrupacion_para(agrupaciones, establecimiento):
        """Devuelve la agrupación a la que pertenece este campo, o None."""
        key = normalize_name(establecimiento)
        for ag in agrupaciones:
            for c in ag["campos"]:
                if normalize_name(c["establecimiento"]) == key:
                    return ag
        return None

    @staticmethod
    def repartir_movimiento(mov, agrupaciones, has_por_campania_cache, db):
        """Dada una fila de 'campos' (movimiento), devuelve una lista de pseudo-movimientos
        con los importes repartidos según las reglas.

        Reglas (en orden):
        1. Si establecimiento es "TODOS" → reparto GLOBAL entre todos los campos
           con has cargadas de esa campaña, según el sector (agrícolas o ganaderas).
        2. Si está en el principal de una agrupación + Sector=Ganadero + Rubro != Arrendamiento
           → se reparte entre los campos del grupo.
        3. En cualquier otro caso → queda tal cual.
        """
        estab = (mov.get("establecimiento") or "").strip()

        # === Caso 1: TODOS (reparto global) ===
        if estab.upper().startswith("TODOS"):
            camp = mov.get("campania") or ""
            if not camp:
                return [mov]
            sector = (mov.get("sector") or "").strip()
            if sector not in ("Agrícola", "Ganadero"):
                return [mov]
            cache_key = ("__global__", camp)
            if cache_key not in has_por_campania_cache:
                has_por_campania_cache[cache_key] = \
                    AgrupacionRepartidor.has_global_campania(db, camp)
            has_global = has_por_campania_cache[cache_key]
            props = AgrupacionRepartidor.proporciones_globales(has_global, sector)
            if not props:
                return [mov]
            out = []
            for e_dest, prop in props.items():
                nuevo = dict(mov)
                nuevo["establecimiento"] = e_dest
                nuevo["monto"] = (mov.get("monto") or 0) * prop
                nuevo["_repartido_de"] = "TODOS"
                nuevo["_proporcion"] = prop
                out.append(nuevo)
            return out

        # === Caso 2: reparto por agrupación ===
        ag = AgrupacionRepartidor.encontrar_agrupacion_para(agrupaciones, estab)
        if ag is None:
            return [mov]
        # Sólo se reparte cuando viene del campo principal
        if normalize_name(estab) != normalize_name(ag["campo_principal"]):
            return [mov]
        # Sólo Sector=Ganadero
        if (mov.get("sector") or "").strip().lower() != "ganadero":
            return [mov]
        # Excluir Arrendamientos
        if AgrupacionRepartidor.es_arrendamiento(mov.get("rubro")):
            return [mov]
        # OK: repartir
        camp = mov.get("campania") or ""
        if not camp:
            return [mov]
        cache_key = (ag["id"], camp)
        if cache_key not in has_por_campania_cache:
            has_por_campania_cache[cache_key] = AgrupacionRepartidor.has_por_campania(
                db, ag["id"], camp)
        has_dict = has_por_campania_cache[cache_key]
        props = AgrupacionRepartidor.proporciones(has_dict)
        if not props:
            return [mov]
        out = []
        for establecimiento, prop in props.items():
            nuevo = dict(mov)
            nuevo["establecimiento"] = establecimiento
            nuevo["monto"] = (mov.get("monto") or 0) * prop
            nuevo["_repartido_de"] = mov["establecimiento"]
            nuevo["_proporcion"] = prop
            out.append(nuevo)
        return out

    @staticmethod
    def repartir_stock(stock_dict, agrupaciones, campania, db):
        """Reparte el stock de los campos principales entre los campos de su grupo.

        stock_dict: {establecimiento: {categoria: cantidad}}
        Devuelve: stock_dict modificado con el reparto aplicado.
        """
        if not stock_dict or not agrupaciones or not campania:
            return stock_dict

        out = {}
        # Copiar todo lo que no es principal de una agrupación tal cual
        principales_agrupados = set()
        agrupaciones_por_principal = {}
        for ag in agrupaciones:
            k = normalize_name(ag["campo_principal"])
            principales_agrupados.add(k)
            agrupaciones_por_principal[k] = ag

        for estab, cats in stock_dict.items():
            ek = normalize_name(estab)
            if ek in principales_agrupados:
                continue  # se procesa abajo
            # Está fuera de cualquier grupo: tal cual
            out.setdefault(estab, {})
            for cat, cant in cats.items():
                out[estab][cat] = out[estab].get(cat, 0) + cant

        # Ahora repartir el stock de cada principal
        for estab, cats in stock_dict.items():
            ek = normalize_name(estab)
            if ek not in principales_agrupados:
                continue
            ag = agrupaciones_por_principal[ek]
            has_dict = AgrupacionRepartidor.has_por_campania(db, ag["id"], campania)
            props = AgrupacionRepartidor.proporciones(has_dict)
            if not props:
                # Sin info: dejar tal cual en el principal
                out.setdefault(estab, {})
                for cat, cant in cats.items():
                    out[estab][cat] = out[estab].get(cat, 0) + cant
                continue
            for cat, cant in cats.items():
                for campo_dest, prop in props.items():
                    out.setdefault(campo_dest, {})
                    # Acumular (puede que el destino ya tuviera algo)
                    out[campo_dest][cat] = out[campo_dest].get(cat, 0) + cant * prop
        return out



class StyledButton(Button):
    def __init__(self, parent, text, command=None, kind="primary", **kw):
        colors = {
            "primary": (COLORS["primary"], "#FFFFFF", COLORS["primary_hi"]),
            "ok": (COLORS["ok"], "#FFFFFF", "#2E6B2E"),
            "danger": (COLORS["danger"], "#FFFFFF", "#A23B2C"),
            "ghost": (COLORS["panel"], COLORS["primary"], COLORS["bg"]),
        }
        bg, fg, hover = colors.get(kind, colors["primary"])
        super().__init__(
            parent, text=text, command=command,
            bg=bg, fg=fg, activebackground=hover, activeforeground=fg,
            font=(FONT_FAMILY, 10, "bold"),
            relief="flat", bd=0, padx=18, pady=8, cursor="hand2", **kw
        )
        self._bg = bg
        self._hover = hover
        self.bind("<Enter>", lambda e: self.configure(bg=hover))
        self.bind("<Leave>", lambda e: self.configure(bg=self._bg))


class LabeledEntry(Frame):
    def __init__(self, parent, label, width=20, **kw):
        super().__init__(parent, bg=COLORS["panel"])
        Label(self, text=label, bg=COLORS["panel"], fg=COLORS["text"],
              font=(FONT_FAMILY, 9, "bold")).pack(anchor=W)
        self.var = StringVar()
        self.entry = Entry(self, textvariable=self.var, width=width,
                           font=(FONT_FAMILY, 10), bd=1, relief="solid",
                           bg="#FFFFFF", fg=COLORS["text"], **kw)
        self.entry.pack(fill=X, pady=(2, 0), ipady=4)

    def get(self): return self.var.get()
    def set(self, v): self.var.set(v if v is not None else "")


class LabeledFecha(Frame):
    """Igual interfaz que LabeledEntry, pero usa un calendario (tkcalendar) si está
    disponible. Para fechas en formularios.

    Métodos: get() devuelve ISO 'YYYY-MM-DD' o "" si está vacío.
             set(v) acepta ISO, dd/mm/aaaa o vacío.
    Por defecto, arranca con la fecha de hoy si permitir_vacio=False.
    """
    def __init__(self, parent, label, width=14, permitir_vacio=False, valor_inicial=None):
        super().__init__(parent, bg=COLORS["panel"])
        Label(self, text=label, bg=COLORS["panel"], fg=COLORS["text"],
              font=(FONT_FAMILY, 9, "bold")).pack(anchor=W)
        # Default: hoy si no permite vacío y no se pasó nada
        if valor_inicial is None and not permitir_vacio:
            valor_inicial = dt.date.today().isoformat()
        wrap = Frame(self, bg=COLORS["panel"])
        wrap.pack(fill=X, pady=(2, 0))
        self.widget, self._get_fn, self._set_fn = crear_fecha_widget(
            wrap, valor_inicial=valor_inicial, width=width, permitir_vacio=permitir_vacio)
        self.widget.pack(fill=X, ipady=2)

    def get(self):
        """Devuelve la fecha en formato dd/mm/aaaa para mantener compatibilidad
        con el código que valida con parse_fecha(). Si está vacía, devuelve ""."""
        iso = self._get_fn()
        if not iso:
            return ""
        try:
            d = dt.datetime.strptime(iso, "%Y-%m-%d").date()
            return d.strftime("%d/%m/%Y")
        except Exception:
            return iso

    def set(self, v):
        self._set_fn(v if v is not None else "")


class LabeledCombo(Frame):
    def __init__(self, parent, label, values, width=18, on_change=None):
        super().__init__(parent, bg=COLORS["panel"])
        Label(self, text=label, bg=COLORS["panel"], fg=COLORS["text"],
              font=(FONT_FAMILY, 9, "bold")).pack(anchor=W)
        self.var = StringVar()
        self.combo = ttk.Combobox(self, textvariable=self.var,
                                  values=values, width=width-2,
                                  state="readonly", font=(FONT_FAMILY, 10))
        self.combo.pack(fill=X, pady=(2, 0), ipady=2)
        if on_change:
            self.combo.bind("<<ComboboxSelected>>", lambda e: on_change())

    def get(self): return self.var.get()
    def set(self, v): self.var.set(v if v is not None else "")
    def set_values(self, values):
        cur = self.var.get()
        self.combo["values"] = values
        if cur not in values:
            self.var.set("")


