class LibroIVAContainer(Frame):
    """Pestaña 'Libro de IVA' con 3 sub-pestañas: Compras / Ventas / Resumen."""
    def __init__(self, parent, db):
        super().__init__(parent, bg=COLORS["bg"])
        self.db = db
        nb = ttk.Notebook(self)
        nb.pack(fill=BOTH, expand=True)
        self.f_compras = IVAComprasFrame(nb, db)
        nb.add(self.f_compras, text="  🧾 IVA Compras  ")
        self.f_ventas = IVAVentasFrame(nb, db)
        nb.add(self.f_ventas, text="  🧾 IVA Ventas  ")
        self.f_resumen = IVAResumenFrame(nb, db)
        nb.add(self.f_resumen, text="  📊 Resumen  ")
        self.nb = nb
        nb.bind("<<NotebookTabChanged>>", self._on_subtab)

    def _on_subtab(self, event=None):
        try:
            tab = self.nb.tab(self.nb.select(), "text").strip()
            if "Resumen" in tab:
                self.f_resumen.refrescar()
            elif "Ventas" in tab:
                self.f_ventas.refrescar()
            elif "Compras" in tab:
                self.f_compras.refrescar()
        except Exception:
            pass

    def on_tab_shown(self):
        try:
            self.f_compras.refrescar()
            self.f_ventas.refrescar()
            self.f_resumen.refrescar()
        except Exception:
            pass


class IVAComprasFrame(Frame):
    """IVA Compras: carga de comprobantes con cálculo automático de IVA,
    tabla con scroll horizontal y panel de detalle al seleccionar."""
    ALICUOTAS = {"neto_27": 0.27, "neto_21": 0.21, "neto_105": 0.105}

    def __init__(self, parent, db):
        super().__init__(parent, bg=COLORS["bg"])
        self.db = db
        self.editing_id = None
        self._build()
        self.refrescar()

    def _build(self):
        # Scroll general vertical para toda la pantalla (el formulario es alto).
        canvas = Canvas(self, bg=COLORS["bg"], highlightthickness=0)
        vsb = Scrollbar(self, orient=VERTICAL, command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        canvas.pack(side=LEFT, fill=BOTH, expand=True)
        vsb.pack(side=RIGHT, fill=Y)
        inner = Frame(canvas, bg=COLORS["bg"])
        inner_id = canvas.create_window((0, 0), window=inner, anchor=NW)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>", lambda e: canvas.itemconfig(inner_id, width=e.width))
        def _wheel(ev):
            canvas.yview_scroll(int(-1 * (ev.delta / 120)), "units")
        canvas.bind("<Enter>", lambda e: canvas.bind_all("<MouseWheel>", _wheel))
        canvas.bind("<Leave>", lambda e: canvas.unbind_all("<MouseWheel>"))

        Label(inner, text="🧾 IVA Compras", bg=COLORS["bg"], fg=COLORS["primary"],
              font=(FONT_FAMILY, 15, "bold")).pack(anchor=W, padx=14, pady=(8, 0))
        Label(inner, text="Cargá cada comprobante. El neto va en la columna de su alícuota; "
              "el IVA y el total se calculan solos (podés corregirlos si hace falta).",
              bg=COLORS["bg"], fg=COLORS["muted"], font=(FONT_FAMILY, 9),
              wraplength=1100, justify=LEFT).pack(anchor=W, padx=14, pady=(0, 4))

        self._build_gasoil_bar(inner)
        self._build_form(inner)
        self._build_tabla(inner)

