        self.v_rub = StringVar()
        self.cb_rub = ttk.Combobox(form, textvariable=self.v_rub,
                                   values=[r[1] for r in RUBROS_IVA], width=26,
                                   state="readonly", font=(FONT_FAMILY, 10))
        self.cb_rub.grid(row=15, column=0, columnspan=2, padx=4, pady=2, sticky=W)

        Label(form, text="Rubro 2 (sub-rubro)", bg=COLORS["panel"], font=(FONT_FAMILY, 9)).grid(row=14, column=2, sticky=W, padx=4)
        self.v_rub2 = StringVar()
        self.cb_rub2 = ttk.Combobox(form, textvariable=self.v_rub2,
                                    values=SUBRUBROS_IVA, width=20, font=(FONT_FAMILY, 10))
