        bar = Frame(form, bg=COLORS["panel"])
        bar.grid(row=16, column=0, columnspan=8, sticky=W, pady=(12, 0))
        self._btn_guardar = StyledButton(bar, "💾 Guardar comprobante", command=self._guardar, kind="ok")
