        interp_frame.pack(fill=X, padx=12, pady=(4, 8))
        Label(interp_frame, text="📖 Interpretación",
              bg="#EBF2F9", fg=COLORS["primary"],
              font=(FONT_FAMILY, 11, "bold")).pack(anchor=W)
        self.txt_interp = Text(interp_frame, height=11, wrap=WORD,
                                 bg="#FAFAFA", fg=COLORS["text"],
                                 font=(FONT_FAMILY, 10),
                                 relief="flat", padx=8, pady=6)
        self.txt_interp.pack(fill=X, pady=(4, 0))
        self.txt_interp.configure(state="disabled")

        # ---- Detalle de Ventas y Gastos por Rubro ----
        details = Frame(inner, bg=COLORS["bg"])
        details.pack(fill=BOTH, expand=True, padx=12, pady=(4, 8))

        ventas_box = Frame(details, bg=COLORS["panel"], padx=8, pady=8,
                            highlightthickness=1, highlightbackground=COLORS["border"])
        ventas_box.pack(side=LEFT, fill=BOTH, expand=True, padx=(0, 6))
        Label(ventas_box, text="✓ Ventas por Rubro",
              bg=COLORS["panel"], fg=COLORS["ok"],
              font=(FONT_FAMILY, 11, "bold")).pack(anchor=W, pady=(0, 4))
        self.tree_ventas = ttk.Treeview(ventas_box,
                                          columns=("rubro", "monto", "pct"),
                                          show="headings", height=8)
