        self.tree_ventas.column("monto", width=140, anchor=E)
        self.tree_ventas.column("pct", width=70, anchor=E)
        self.tree_ventas.pack(fill=BOTH, expand=True)
        self.tree_ventas.tag_configure("total", background=COLORS["ok"],
                                         foreground="#FFFFFF",
                                         font=(FONT_FAMILY, 10, "bold"))

        gastos_box = Frame(details, bg=COLORS["panel"], padx=8, pady=8,
                            highlightthickness=1, highlightbackground=COLORS["border"])
        gastos_box.pack(side=LEFT, fill=BOTH, expand=True, padx=(6, 0))
        Label(gastos_box, text="✗ Gastos por Rubro",
              bg=COLORS["panel"], fg=COLORS["danger"],
              font=(FONT_FAMILY, 11, "bold")).pack(anchor=W, pady=(0, 4))
