# DASHBOARD - VISTA INTEGRAL DE TODA LA INFORMACIÓN
# ============================================================
def dibujar_barras_horizontales(canvas, datos, ancho_total=600, alto_barra=22,
                                  espaciado=6, color_barra=None, mostrar_valores=True):
    """Dibuja barras horizontales en un Canvas tk.

    datos: lista de dicts con keys 'label', 'valor' (numérico), opcional 'color'
    canvas: tk Canvas donde dibujar
    Devuelve la altura total dibujada (para configurar scrollregion).
    """
    canvas.delete("all")
    if not datos:
        canvas.create_text(ancho_total / 2, 30, text="(sin datos)",
                           fill=COLORS["muted"], font=(FONT_FAMILY, 10, "italic"))
        return 60

    max_v = max(abs(d["valor"]) for d in datos) or 1
    label_w = 200  # ancho de la etiqueta a la izquierda
    valor_w = 130  # ancho del número a la derecha
    bar_max_w = max(ancho_total - label_w - valor_w - 20, 100)

    y = 8
    for d in datos:
        label = d["label"]
        valor = d["valor"]
        color = d.get("color") or color_barra or COLORS["primary"]
        if len(label) > 35:
            label = label[:32] + "..."
        # Label
        canvas.create_text(label_w - 6, y + alto_barra / 2,
                            text=label, anchor=E,
                            font=(FONT_FAMILY, 9), fill=COLORS["text"])
        # Barra
        w = abs(valor) / max_v * bar_max_w if max_v else 0
        canvas.create_rectangle(label_w, y, label_w + max(w, 1), y + alto_barra,
                                 fill=color, outline=color)
        # Valor numérico
        if mostrar_valores:
            txt = fmt_money(valor) if abs(valor) > 100 else f"{valor:,.1f}"
            canvas.create_text(label_w + bar_max_w + 8, y + alto_barra / 2,
                                text=txt, anchor=W,
                                font=(FONT_FAMILY, 9, "bold"), fill=COLORS["text"])
        y += alto_barra + espaciado
    return y + 8


class DashboardFrame(Frame):
    """Dashboard integral con KPIs, gráficos, alertas y conclusiones.

    Combina información de las 3 fuentes:
    - CAMPOS (lo agropecuario)
    - CAMPAMENTO (gastos operativos del campo)
    - GTOS PARTICULARES (gastos personales/familiares)

    Filtros simples (campaña/campo) actualizan automático; cálculos pesados
    requieren apretar el botón 'Actualizar Dashboard'.
    """

    def __init__(self, parent, db):
        super().__init__(parent, bg=COLORS["bg"])
        self.db = db
        self.ultimo_data = None
        self._build()
        self._actualizar_listas()

    def _build(self):
        # Canvas scrolleable principal
        canvas = Canvas(self, bg=COLORS["bg"], highlightthickness=0)
        vsb = Scrollbar(self, orient=VERTICAL, command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        canvas.pack(side=LEFT, fill=BOTH, expand=True)
        vsb.pack(side=RIGHT, fill=Y)
        inner = Frame(canvas, bg=COLORS["bg"])
        inner_id = canvas.create_window((0, 0), window=inner, anchor=NW)
        def on_cfg(e): canvas.configure(scrollregion=canvas.bbox("all"))
        inner.bind("<Configure>", on_cfg)
        def on_resize(e): canvas.itemconfig(inner_id, width=e.width)
        canvas.bind("<Configure>", on_resize)
        def on_wheel(e):
            canvas.yview_scroll(int(-1 * (e.delta / 120)), "units")
        canvas.bind("<Enter>", lambda e: canvas.bind_all("<MouseWheel>", on_wheel))
        canvas.bind("<Leave>", lambda e: canvas.unbind_all("<MouseWheel>"))

        # Cabecera
        head = Frame(inner, bg=COLORS["bg"])
        head.pack(fill=X, padx=12, pady=(12, 4))
        Label(head, text="📊 Dashboard Integral",
              bg=COLORS["bg"], fg=COLORS["primary"],
              font=(FONT_FAMILY, 16, "bold")).pack(side=LEFT)

        Label(inner,
              text="Vista integral de la actividad: campos, campamento y gastos particulares. "
                   "Apretá 'Actualizar Dashboard' para recalcular con los filtros elegidos.",
              bg=COLORS["bg"], fg=COLORS["muted"],
              font=(FONT_FAMILY, 9, "italic"),
              wraplength=1200, justify=LEFT).pack(anchor=W, padx=14, pady=(0, 4),
                                                    fill=X)

        # Cartel amarillo con notas IMPORTANTES sobre el uso del filtro de campaña
        # y el momento ideal para usar el dashboard.
        notas_frame = Frame(inner, bg="#FFF8E5", padx=12, pady=8,
                              highlightthickness=2, highlightbackground=COLORS["accent"])
        notas_frame.pack(fill=X, padx=14, pady=(0, 8))
        Label(notas_frame, text="💡 Notas importantes:",
              bg="#FFF8E5", fg=COLORS["primary"],
              font=(FONT_FAMILY, 10, "bold")).pack(anchor=W)
        Label(notas_frame,
              text="• El Balance Operativo se calcula con los movimientos entre las fechas seleccionadas (igual que siempre).\n"
                   "• La Valuación del Stock tiene dos modos (selectores arriba a la derecha):\n"
                   "    🏛 Patrimonial: TODO el ganado + cereal sin vender de esta campaña y anteriores (excluye campañas futuras).\n"
                   "    📅 Resultado del ejercicio: solo Terneras/Terneros de ganado + cereal solo de la campaña seleccionada.\n"
                   "• Para una vista patrimonial fiel, conviene haber cargado los kg cosechados de la campaña correspondiente; "
                   "sino el Val. Stock Cereal queda subestimado.",
              bg="#FFF8E5", fg=COLORS["text"],
              font=(FONT_FAMILY, 9),
              wraplength=1180, justify=LEFT).pack(anchor=W, pady=(2, 0), fill=X)

        # ---- Filtros ----
        filt = Frame(inner, bg=COLORS["panel"], padx=12, pady=10,
                      highlightthickness=1, highlightbackground=COLORS["border"])
        filt.pack(fill=X, padx=12, pady=(2, 6))

        Label(filt, text="Fecha desde (dd/mm/aaaa):",
              bg=COLORS["panel"], fg=COLORS["text"],
              font=(FONT_FAMILY, 9, "bold")).grid(row=0, column=0, padx=4, pady=4, sticky=W)
        w_d, self._get_desde, self._set_desde = crear_fecha_widget(
            filt, valor_inicial=None, width=12, permitir_vacio=True)
        w_d.grid(row=0, column=1, padx=4, pady=4, sticky=W)

        Label(filt, text="Fecha hasta:",
              bg=COLORS["panel"], fg=COLORS["text"],
              font=(FONT_FAMILY, 9, "bold")).grid(row=0, column=2, padx=(14, 4), pady=4, sticky=W)
        w_h, self._get_hasta, self._set_hasta = crear_fecha_widget(
            filt, valor_inicial=None, width=12, permitir_vacio=True)
        w_h.grid(row=0, column=3, padx=4, pady=4, sticky=W)

        Label(filt, text="Campaña:",
              bg=COLORS["panel"], fg=COLORS["text"],
              font=(FONT_FAMILY, 9, "bold")).grid(row=0, column=4, padx=(14, 4), pady=4, sticky=W)
        self.var_camp = StringVar()
        self.cmb_camp = ttk.Combobox(filt, textvariable=self.var_camp, width=12,
                                       state="readonly", font=(FONT_FAMILY, 10))
        self.cmb_camp.grid(row=0, column=5, padx=4, pady=4, sticky=W)

        Label(filt, text="Campo:",
              bg=COLORS["panel"], fg=COLORS["text"],
              font=(FONT_FAMILY, 9, "bold")).grid(row=0, column=6, padx=(14, 4), pady=4, sticky=W)
        self.var_campo = StringVar(value="TODOS")
        self.cmb_campo = ttk.Combobox(filt, textvariable=self.var_campo, width=22,
                                        state="readonly", font=(FONT_FAMILY, 10))
        self.cmb_campo.grid(row=0, column=7, padx=4, pady=4, sticky=W)

        # Selector de modo de valuación del stock (igual a Análisis por Campo)
        modo_box = Frame(filt, bg=COLORS["panel"])
        modo_box.grid(row=0, column=8, padx=(14, 4), pady=4, sticky=W)
