        w_fd.grid(row=0, column=1, padx=2, sticky=W)
        Label(filt, text="Hasta:", bg=COLORS["panel"], font=(FONT_FAMILY, 9, "bold")).grid(row=0, column=2, padx=(10, 2), sticky=W)
        w_fh, self.get_fh, self.set_fh = crear_fecha_widget(filt, valor_inicial=None, width=11, permitir_vacio=True)
        w_fh.grid(row=0, column=3, padx=2, sticky=W)
        Label(filt, text="Banco:", bg=COLORS["panel"], font=(FONT_FAMILY, 9, "bold")).grid(row=0, column=4, padx=(10, 2), sticky=W)
        self.var_banco_filt = StringVar(value="TODOS")
