        StyledButton(filt, "🔍 Aplicar filtros", command=self.refrescar, kind="primary").grid(row=1, column=5, padx=(10, 4), pady=(6, 0))
        StyledButton(filt, "Limpiar", command=self._limpiar_filtros, kind="ghost").grid(row=1, column=6, padx=4, pady=(6, 0))

        bar_c = Frame(inner, bg=COLORS["bg"])
